COLLDATA("tadabburar","ar",[[541,"§الحديد\nwords\nبِالبَيِّنَاتِبِالحُجَجِ الوَاضِحَاتِ.\nوَالمِيزَانَالعَدلَ فِي الأَقوَالِ، وَالأَفعَالِ.\nبَأسٌقُوَّةٌ.\nعَزِيزٌغَالِبٌ لاَ يُغلَبُ.\nقَفَّينَا عَلَى آثَارِهِمأَتبَعنَاهُم، وَبَعَثنَا بَعدَهُم.\nوَرَهبَانِيَّةًغُلُوًّا فِي التَّعَبُّدِ.\nمَا كَتَبنَاهَامَا فَرَضنَاهَا.\nفَمَا رَعَوهَامَا قَامُوا بِهَا حَقَّ القِيَامِ، بَل بَدَّلُوا وَخَالَفُوا.\nكِفلَينِضِعفَينِ.\ndeeds\nعدد ثلاثة من مظاهر قوة الله -تبارك وتعالى- فيما تراه وتشاهده من حولك.\nادعُ الله أن ينصر هذا الدين.\nتبرع لعمل خيري لنصرة هذا الدين.\nguid\nبالعدل قامت السماوات والأرض؛ فاحرص على العدل في جميع شؤونك.\nما من كلمة أو فعلة تنصر بها دين الله إلا وهي محسوبة لك.\nالفضل والخير خزائنه بيد الله تعالى وحده.\nrefl\nلَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ\nإقامة دين الإسلام تنبني على أمرين؛ أحدهما: هو ما ذكره بقوله: ﴿وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ﴾؛ لأن في ذلك إقامة البراهين على الحق، وبيان الحجة، وإيضاح الأمر والنهي والثواب والعقاب. فإذا أصر الكفار على الكفر وتكذيب الرسل مع ذلك البيان والإيضاح؛ فإن الله -تبارك وتعالى- أنزل الحديد؛ أي: خلقه لبني آدم؛ ليردع به المؤمنون الكافرين المعاندين؛ وهو قتلهم إياهم بالسيوف والرماح والسهام. الشنقيطي:٧/٥٤٩.\nإقامة دين الإسلام تنبني على أمرين فما هما؟\nلَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ\nأي: وجعلنا الحديد رادعًا لمن أبى الحق وعانده بعد قيام الحجة عليه، ولهذا أقام رسول الله -صلى الله عليه وسلم- بمكة بعد النبوة ثلاث عشرة سنة توحَى إليه السور المكية، وكلها جدال مع المشركين وبيان وإيضاح للتوحيد وبيانات ودلالات، فلما قامت الحجة على من خالف شرع الله أمرهم بالهجرة، وأمرهم بالقتال بالسيوف وضرب الرقاب والهامّ لمن خالف القرآن وكذب به وعانده. ابن كثير:٤/٣١٥.\nلماذا قدم ذكر إنزال الكتب على إنزال الحديد؟\nوَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ٢٥\nونصرُ الناس الله هو نصرهم دينه؛ وأمَّا الله فغني عن النصر. وعطف (ورسله) أي: من ينصر القائمين بدينه، ويدخل فيه نصر شرائع الرسول بعده. ابن عاشور:٢٧/٤١٨.\nما المقصود بنصر الله ورسله في الآية الكريمة؟\nوَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ\nكان النصارى ألين من غيرهم قلوبًا حين كانوا على شريعة عيسى -عليه السلام-. السعدي:٨٤٣.\nمتى كان النصارى ألين قلوبًا تجاه المؤمنين؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِ\nأي خافوا عقابه، فاجعلوا بينكم وبين سخطه -لأنه الملك الأعظم- وقايةٌ؛ بحفظ الأدب معه، ولا تأمنوا مكره؛ فكونوا على حذر من أن يسلبكم ما وهبكم، فاتبعوا الرسول تسلموا، وحافظوا على اتباعه لئلَّا تهلكوا. البقاعي:١٩/٣٢٤.\nما عقوبة من تجرد من التقوى والخوف من الله؟\nوَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِ\nأي: بيانًا وهدى. وقال ابن عباس: \"هو القرآن\". وقيل: ضياء تمشون به في الآخرة على الصراط. وقيل: تمشون به في الناس تدعونهم إلى الإسلام؛ فتكونوا رؤساء في دين الإسلام، لا تزول عنكم رياسة كنتم فيها؛ وذلك أنهم خافوا أن تزول رياستهم لو آمنوا بمحمد -عليه السلام-. القرطبي:٢٠/٢٧٨.\nما النور الذي يجعله الله تعالى لهؤلاء؟\nوَٱللَّهُ غَفُورٞ رَّحِيمٞ ٢٨\nأي: مالكه ملكًا لا ينفك عنه، ولا ملك لأحد فيه معه، ولا تصرُّف بوجه أصلًا؛ فلذلك يخص من يشاء بما يشاء، فلا يقدر أحد على اعتراض بوجه. البقاعي:١٩/٣٣٠.\nما دلالة وصف الله تعالى بأنه صاحب الفضل العظيم؟"],[542,"§المجادلة\nwords\nتُجَادِلُكَتُرَاجِعُكَ، وَهِيَ: خَولَةُ بِنتُ ثَعلَبَةَ.\nزَوجِهَاأَوسِ بنِ الصَّامِتِ.\nوَزُورًاكَذِبًا.\nفَتَحرِيرُ رَقَبَةٍعِتقُ رَقَبَةٍ مُؤمِنَةٍ؛ عَبدٍ، أَو أَمَةٍ.\nيَتَمَآسَّايَستَمتِعَا بِالجِمَاعِ.\nيُحَآدُّونَيُشَاقُّونَ وَيُخَالِفُونَ.\nكُبِتُواخُذِلُوا، وَأُهِينُوا.\ndeeds\nتضرع إلى الله بقولك: \"اللهم إني أشكو إليك ضعف قوتي، وقلة حيلتي، وهواني على الناس\"، ثم ادع الله بما أهمك.\nتصدق أو ساعد امرأة ضعيفة أو مسكينة أو مظلومة.\nتذكر ذنبًا فعلته واستغفر الله منه.\nguid\nسعة علم الله وإحاطته وسمعه للأصوات.\nاحذر أن تتعدى حدود الله.\nاحذر من كل عمل يسوءك في يوم القيامة فإن كل عمل مُحصَى عليك خيرًا كان أو شرًا.\nrefl\nإِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ١\nوهذا إخبار عن كمال سمعه وبصره، وإحاطتهما بالأمور الدقيقة والجليلة. وفي ضمن ذلك الإشارة بأن الله تعالى سيزيل شكواها، ويرفع بلواها. السعدي: ٨٤٤.\nلماذا اختتمت الآية بهذين الاسمين الكريمين؟\nٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ٢\nيعلم من الآيات أن الظهار حرام، بل قالوا: إنه كبير؛ لأن فيه إقدامًا على إحالة حكم الله تعالى وتبديله بدون إذنه، وهذا أخطر من كثير من الكبائر. الألوسي: ١٤/٢٠٠.\nما دلالة وصف الظهار بالمنكر والزور؟\nوَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ\nوالفرق بين جهة كونه منكرًا وجهةِ كونه زورًا؛ أن قوله: \"أنتِ عليَّ كظهر أمي\" يتضمنُ إخباره عنها بذلك، وإنشاءَه تحريمها؛ فهو يتضمن إخبارًا وإنشاءً، فهو خبرٌ زورٌ وإنشاءٌ منكر؛ فإن الزور هو الباطل خلاف الحق الثابت، والمنكر خلاف المعروف. ابن القيم: ٣/١٣٩.\nلماذا وُصِفَ الظهار بأنه منكر وبأنه زور؟\nذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِه\nذلك الحكم الذي بيناه لكم ووضحناه لكم لتؤمنوا بالله ورسوله؛ وذلك بالتزام هذا الحكم وغيره من الأحكام والعمل به؛ فإن التزام أحكام الله والعمل بها من الإيمان، بل هي المقصودة ومما يزيد به الإيمان ويكمل وينمو. السعدي: ٨٤٤.\nبيّن العلاقة بين العمل الصالح والإيمان من خلال الآية.\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ\nأي: أهلكوا، وقال قتادة: \"أخزوا كما أخزي الذين من قبلهم\"، وقيل: عذبوا، وقيل: غيظوا يوم الخندق، وقيل: أي: سيكبتون. وهو بشارة من الله تعالى للمؤمنين بالنصر. القرطبي: ٢٠/٣٠٥.\nما المراد بقوله (كبتوا)؟ وما البشارة من هذه الآية؟\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۢ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ ٥\nثَبَتَ أن المحادَّ مكبوتٌ مخزيٌّ ممتل غيظًا وحزنًا هالك. وهذا إنَّما يَتِمُّ إذا خاف إن أظهر المحادة أن يُقتَل، وإلا فمن أمكنه إظهار المحادَّة وهو آمن على دمه وماله فليس بمكبُوتٍ، بل مسرور جذلان. ولأنه قال: ﴿كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ﴾ والذين من قبلهم ممن حاد الرسل، وحادّ رسول الله إنَّما كبته الله بأن أهلكه بعذابٍ من عنده أو بأيدي المؤمنين. ابن تيمية: ٦/٢٤٠.\nمحَادَّة الله ورسولَه تورث أمراض القلب في الدنيا وعذاب الله في الآخرة؛ وضّح ذلك.\nيَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ٦\nوجملة: (أحصاه الله ونسوه) مستأنفة جواب سؤال مقدر؛ كأنه قيل: كيف ينبئهم بذلك على كثرته واختلاف أنواعه؟ فقيل: أحصاه الله جميعًا ولم يفُته منه شيء، والحال أَنهم قَد نسوه ولَم يحفَظُوه، بل وجدوه حاضرًا مكتوبًا في صحائفهم. الشوكاني: ٥/١٨٦.\nهناك سؤال مقدر جوابه جملة (أحصاه الله ونسوه) ما هو؟"],[543,"§المجادلة\nwords\nبِمَا لَم يُحَيِّكَ بِهِ اللهُقَالُوا لَكَ: السَّامُ عَلَيكُم، أَيِ: المَوتُ لَكَ.\nلَولاَهَلاَّ.\nحَسبُهُمكَافِيَتُهُم.\nالمَصِيرُالمَرجِعُ، وَالمَآلُ.\nإِنَّمَا النَّجوَىالتَّحَدُّثُ بِخُفيَةٍ بِالإِثمِ وَالعُدوَانِ.\nتَفَسَّحُوالِيُوسِع بَعضُكُم لِبَعضٍ فِي المَجَالِسِ.\nانشُزُواقُومُوا مِن مَجَالِسِكُم لأَمرٍ فِيهِ خَيرٌ لَكُم.\ndeeds\nاجلس مع مسلم وتكلم في موضوع يزيد من إيمانك، وتناجوا بالبر والتقوى.\nأحسن الظن بالمؤمنين؛ فإن النجوى لا تكون إلا عن سوء ظن.\nافسح لأخيك في الحلقة والمجلس والدرس يفسح الله لك.\nguid\nتذكر سعة علم الله تعالى وأنه لا تخفى عليه خافية.\nإذا أتاك الحزن فاعلم أن مصدره الشيطان؛ فهو يقصد إدخال الحزن على قلبك.\nمن علاجات الحزن التوكل على الله.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ ٧\nافتتح الكلام بالعلم، وختمه بالعلم؛ ولهذا قال ابن عباس والضحاك وسفيان الثوري وأحمد بن حنبل: \"هو معهم بعلمه\". ابن تيمية: ٦/٢٤١.\nكيف تستدل بالآية على أن المعية في قوله: ﴿وَهُوَ مَعَهُمۡ﴾ هي بالعلم وليست بذات الله تعالى؟\nوَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ\nكانوا إذا دخلوا على النبي -صلى الله عليه وسلم- يخفتون لفظ (السلام عليكم)؛ لأنه شعار الإسلام، ولما فيه من جمع معنى السلامة؛ يعدلون عن ذلك ويقولون: (أَنعِم صباحًا)، وهي تحية العرب في الجاهلية؛ لأنهم لا يحبون أن يتركوا عوائد الجاهلية. ابن عاشور: ٢٨/٣١.\nما رأيك في أنواع التحية المنتشرة بين بعض الشباب اليوم؟ وما أفضل تحية؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\nوالتفسيح المأمور به هو التوسع دون القيام؛ ولذلك قال رسول الله -صلى الله عليه وسلم-: «لا يقم أحد من مجلسه ثم يجلس الرجل فيه، ولكن تفسحوا وتوسعوا». ابن جزي: ٢/٤٢٢.\nبيّن الأدب الشرعي الذي أمرت به هذه الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\n﴿يَفۡسَحِ ٱللَّهُ لَكُمۡۖ﴾ أي: في قبوركم، وقيل: في قلوبكم، وقيل: يوسع عليكم في الدنيا والآخرة. القرطبي: ٢٠/٣١٨.\nما المراد بفسح الله تعالى للعبد؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ\nوالجزاء من جنس العمل؛ فإنَّ مَن فسح فسح الله له، ومن وسَّع لأخيه وسَّع الله عليه. السعدي: ٨٤٦.\nتحدث عن قاعدة (الجزاء من جنس العمل) من خلال الآية.\nيَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ\nأي: لا تعتقدوا أنه إذا أفسح أحد منكم لأخيه إذا أقبل، أو إذا أمر بالخروج فخرج؛ أن يكون ذلك نقصًا في حقه، بل هو رفعة ورتبة عند الله تعالى. ابن كثير: ٤/٣٢٦.\nهل إفساحك لأخيك في المجلس نقص في حقك؟\nيَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ\nاللام في (العلم) ليست للاستغراق، وإنَّما هي للعهد؛ أي: العلم الذي بعث الله به نبيه -صلى الله عليه وسلم-، وإذا كانوا قد أوتوا هذا العلم كان اتباعهم واجبًا. ابن القيم: ٣/١٤٣.\nكيف دلت الآية على أهمية اتباع العلماء؟"],[544,"§المجادلة\nwords\nالَّذِينَ تَوَلَّوا قَومًاالمُنَافِقِينَ اتَّخَذُوا اليَهُودَ أَصدِقَاءَ، وَوَالَوهُم.\nجُنَّةًوِقَايَةً لَهُم مِنَ القَتلِ.\nوَيَحسَبُونَيَعتَقِدُونَ.\nاستَحوَذَغَلَبَ، وَاستَولَى.\nيُحَآدُّونَيُخَالِفُونَ، وَيُشَاقُّونَ.\nالأَذَلِّينَالأَذِلاَّءِ المَغلُوبِينَ المُهَانِينَ.\nلَأَغلِبَنَّلَأَنتَصِرَنَّ.\ndeeds\nادع لأستاذك أو لشيخك لصبره على تعليمك.\nاحرص على ذكر الله قبل الأكل وبعده وقبل النوم وبعده.\nاحرص على الصلوات الخمس مع الجماعة؛ خاصة الفجر والعصر.\nguid\nالحرص على اتباع سنة النبي -صلى الله عليه وسلم-.\nالمنافقون من حزب الشيطان فاحذرهم واحذر صفاتهم.\nمن صفات حزب الشيطان: الكذب والنفاق وبغض الصحابة.\nrefl\nفَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ\nعدل عن \"فصلوا\" إلى (فَأَقِيمُوا الصَّلاةَ)؛ ليكون المراد المثابرة على توفية حقوق الصلاة ورعاية ما فيه كمالها، لا على أصل فعلها فقط. الألوسي: ١٤/٢٢٥.\nلماذا عدل عن \"فصلوا\" إلى (فأقيموا الصلاة)؟\nفَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ\nهاتان العباداتان هما أم العبادات البدنية والمالية؛ فمن قام بهما على الوجه الشرعي فقد قام بحقوق الله وحقوق عباده. السعدي: ٨٤٧.\nلماذا خصت هاتان العبادتان بالذكر دون غيرهما؟\nوَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ١٣\n﴿وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ﴾... والعبرة في ذلك على الإخلاص والإحسان؛ ولهذا قال تعالى: ﴿وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ﴾ فيعلم تعالى أعمالهم، وعلى أي وجه صدرت، فيجازيهم على حسب علمه بما في صدورهم. السعدي: ٨٤٧.\nلماذا عقب الطاعة بوصفه بأنه خبير بما نعمل؟\n۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ\nقال القشيري: \"من وافق مغضوبًا عليه أشرك نفسه في استحقاق غضب من هو غضبان عليه؛ فمن تولَّى مغضوبًا عليه من قِبَل الله استوجب غضب الله، وكفى بذلك هوانًا وحزنًا وحرمانًا\". البقاعي: ١٩/٣٨٧.\nما خطورة تولي من غضب الله عليه؟\nيَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ ١٨\nمن عاش على شيء مات عليه؛ فكما أن المنافقين في الدنيا يموِّهون على المؤمنين، ويحلفون لهم أنهم مؤمنون؛ فإذا كان يوم القيامة وبعثهم الله جميعًا، حلفوا لله كما حلفوا للمؤمنين، ويحسبون في حلفهم هذا أنهم على شيء؛ لأن كفرهم ونفاقهم وعقائدهم الباطلة لم تزل ترسخ في أذهانهم شيئًا فشيئًا حتى غرَّتهم وظنوا أنهم على شيء يُعتد به ويعلَّق عليه الثواب. السعدي: ٨٤٨.\nكيف تتشابه حال المنافقين في الآخرة والدنيا؟\nإِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ ٢٠\nولما كانوا لا يفعلون ذلك إلا لكثرة أعوانهم وأتباعهم فيظن من رآهم أنهم الأعزاء الذين لا أحد أعز منهم؛ قال تعالى نفيًا لهذا الغرور الظاهر: (أولئك) أي: الأباعد الأسافل ﴿فِي ٱلۡأَذَلِّينَ﴾ أي: الذين يعرفون أنهم أذل الخلق... قال الحسن: \"إن للمعصية في قلوبهم لذلًا، وإن طقطقت بهم اللجم\". البقاعي: ١٩/٣٩٥.\nما أثر المعصية في القلوب من خلال الآية؟\nكَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ ٢١\nقال الزجاج: \"غلبة الرسل على نوعين: من بعث منهم بالحرب؛ فهو غالب بالحرب، ومن لم يؤمر بالحرب؛ فهو غالب بالحجة\". البغوي: ٤/٣٤٩.\nكيف تَغلِب رسل الله مكذبيهم ومِنَ الرسل مَن قتله قومُه؟"],[545,"§المجادلة ، الحشر\nwords\nيُوَآدُّونَيُحِبُّونَ.\nحَآدَّعَادَى.\nعَشِيرَتَهُمأَقرِبَاءَهُم.\nوَأَيَّدَهُمقَوَّاهُم.\nبِرُوحٍ مِنهُبِنَصرٍ، وَتَأيِيدٍ.\nلَم يَحتَسِبُوالَم يَخطُر لَهُم بِبَالٍ.\nوَقَذَفَأَلقَى.\ndeeds\nقل: \"اللهم إني أسألك رضاك والجنة\".\nسَلِ الله الهداية لك ولوالديك ولإخوانك وعشيرتك.\nقل: \"اللهم إني أعوذ بك من جهد البلاء، ودرك الشقاء، وشماتة الأعداء، وسوء القضاء\".\nguid\nاحرص على أن تكون أخوتك ومحبتك لله لا لمصالح دنيوية.\nمعاداة من حاد الله ورسوله ولو كان أقرب قريب.\nلا يستطيع أحد مهما كانت قوته أن يغلب أمر الله تعالى.\nrefl\nلَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُ\nأي: لا يجتمع هذا وهذا؛ فلا يكون العبد مؤمنًا بالله واليوم الآخر حقيقة إلا كان عاملًا على مقتضى الإيمان ولوازمه: من محبة من قام بالإيمان وموالاته، وبغض من لم يقم به ومعاداته. السعدي: ٨٤٨.\nما العلاقة بين الإيمان بالله واليوم الآخر وبغض من حاد الله ورسوله؟\nلَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُ\nأخبر أنك لا تجد مؤمنًا يواد المحادين لله ورسوله؛ فإن نفس الإيمان ينافي موادته كما ينفي أحد الضدين الآخر؛ فإذا وُجِدَ الإيمان انتفى ضده، وهو موالاة أعداء الله، فإذا كان الرجلُ يوالي أعداء الله بقلبه كان ذلك دليلًا على أن قلبه ليس فيه الإيمان الواجب. ابن تيمية: ٦/٢٥٧.\nلماذا وصفهم الله بالإيمان حينما نفى عنهم موادَّة من حاد الله ورسوله؟\nرَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ\nوفي قوله: ﴿رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ﴾ سر بديع؛ وهو أنه لمَّا سخطوا على القرائب والعشائر في الله تعالى، عوَّضهم الله بالرضى عنهم، وأرضاهم عنه بما أعطاهم من النعيم المقيم والفضل العميم. ابن كثير: ٤/٣٢.\nوضح سبب رضا الله عن المؤمنين ورضاهم عنه من خلال الآية.\nأُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ ٢٢\n(أولئك) أي: الذين هم في الدرجة العليا من العظمة؛ لكونهم قَصَرُوا ودَّهم على الله علمًا منهم بأنه ليس النفع والضر إلا بيده. البقاعي: ١٩/٤٠٠.\nما علامة حزب الله الحقيقي؟\nهُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ\nلا تعتمدوا على غير الله كما اعتمد هؤلاء على المنافقين؛ فإن من اعتمد على مخلوق أسلمه ذلك إلى صغاره ومذلته. البقاعي: ١٩/٤١١.\nما جزاء من يعدل عن الاعتماد على الله تعالى إلى الاعتماد على مخلوق؟\nوَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ\nفأعجبوا بها وغرتهم، وحسبوا أنهم لا يُنالون بها، ولا يقدر عليها أحد... واطمأنت نفوسهم إليها؛ ومن وثق بغير الله فهو مخذول، ومن ركن إلى غير الله فهو عليه وبال. السعدي: ٨٤٩.\nفي الآية حث على التوكل على الله -سبحانه وتعالى- وعدم الركون إلى الأسباب، بين ذلك.\nيُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ ٢\nأي: تفكروا في عاقبة من خالف أمر الله، وخالف رسوله، وكذَّب كتابه؛ كيف يحل به من بأسه المخزي له في الدنيا مع ما يدخره له في الآخرة من العذاب الأليم. ابن كثير: ٤/٣٣١.\nما العبرة المستفادة من قصة بني النضير؟"],[546,"§الحشر\nwords\nلِينَةٍنَخلَةٍ، أَو نَوعٍ مِنَ النَّخلِ.\nوَمَا أَفَاءَ اللهوَمَا رَدَّهُ الله مِن أَموَالِ بَنِي النَّضِيرِ، وَالفَيءُ: مَا أُخِذَ مِن أَموَالِ الكُفَّارِ بِحَقٍّ، مِن غَيرِ قِتَالٍ، والغَنِيمَةُ: مَا أُخِذَ بِقِتَالٍ.\nفَمَا أَوجَفتُمفَلَم تَركَبُوا لِتَحصِيلِهِ.\nرِكَابٍمَا يُركَبُ مِنَ الإِبِلِ.\nدُولَةًمُلكًا مُتَدَاوَلًا.\nتَبَوَّءُوا الدَّارَاستَوطَنُوا المَدِينَةَ.\ndeeds\nقدم هدية لمسلم جديد أو طالب علم تغرَّب عن وطنه.\nأعط أحد الفقراء حصتك من الإفطار لهذا اليوم إيثارًا لما عند الله.\nقل: \"اللهم قني شح نفسي\".\nguid\nالأخذ بما أمرت به السنة النبوية، وما نهت عنه.\nربما احتاج الصدق إلى تضحية.\nمن نجا من شح نفسه كان من المفلحين.\nrefl\nذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ٤\n﴿وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ﴾ اقتصر ها هنا على مشاقة الله؛ لأن مشاقته مشاقة لرسوله. الشوكاني: ٥/١٩٦.\nلماذا اقتصر في آخر الآية الكريمة على ذكر مشاقتهم لله تعالى، ولم يذكر مشاقتهم للرسول -صلى الله عليه وسلم- كما ذكرها قبل ذلك؟\nكَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ\nلكيلا يكون الفيء دولة... بين الرؤساء والأقوياء فيغلبوا عليه الفقراء والضعفاء؛ وذلك أن أهل الجاهلية كانوا إذا اغتنموا غنيمة أخذ الرئيس ربعها لنفسه؛ وهو المرباع... فجعله الله لرسوله -صلى الله عليه وسلم- يقسمه فيما أُمر به. البغوي: ٤/٣٥٧.\nما المراد بقوله ﴿كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ﴾؟\nوَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ\nوالقصد من هذا التذييل إزالة ما في نفوس بعض الجيش من حزازة حرمانهم مما أفاء الله على رسوله -صلى الله عليه وسلم- من أرض النضير. ابن عاشور: ٢٨/٨٦.\nما القصد من ختم أحكام الفيء بهذه الخاتمة الكريمة؟\nوَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ\nفأخبر عنهم بأنهم يبذلون ما عندهم من الخير مع الحاجة، وأنهم لا يكرهون ما أنعم به على إخوانهم. وضد الأول البخل، وضد الثاني الحسد. ولهذا كان البخل والحسد من نوع واحد؛ فإن الحاسد يكره عطاء غيره، والباخل لا يحب عطاء نفسه. ابن تيمية: ٦/٢٧٢.\nذكرت الآية للمؤمنين صفتين عظيمتين، فما هما؟\nوَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞ\nوهذا إنَّما هو في فضول الدنيا، لا الأوقات المصروفة في الطاعات؛ فإن الفلاح كل الفلاح في الشح بها؛ فمن لم يكن شحيحًا بوقته تركه الناس على الأرض عيانًا مفلسًا؛ فالشح بالوقت هو عمارة القلب وحفظ رأس ماله. ومما يدل على هذا: أنه سبحانه أمر بالمسابقة في أعمال البر، والتنافس فيها، والمبادرة إليها، وهذا ضد الإيثار بها. ابن القيم: ٣/١٤٦.\nمتى يكون الإيثار محمودًا؟ ومتى يكون الشح محمودًا؟\nوَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞ\nهذا المقام أعلى من حال الذين وصف الله بقوله تعالى: ﴿وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ﴾ [الإنسان: ٨]، ﴿وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ﴾ [البقرة: ١٧٧؛ فإن هؤلاء تصدقوا وهم يحبون ما تصدقوا به، وقد لا يكون لهم حاجة إليه ولا ضرورة به، وهؤلاء آثروا على أنفسهم مع خصاصتهم إلى ما أنفقوه. ابن كثير: ٤/٣٣٨.\nأيهما أفضل: المؤثر على نفسه، أم مؤتي المال على حبه؟\nوَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ٩\nفإنه إذا وُقِي العبد شُحَّ نفسه سمحت نفسه بأوامر الله ورسوله؛ ففعلها طائعًا منقادًا منشرحًا بها صدره، وسمحت نفسه بتركه ما نهى الله عنه وإن كان محبوبًا للنفس تدعو إليه وتطلع إليه، وسمحت نفسه ببذل الأموال في سبيل الله وابتغاء مرضاته؛ وبذلك يحصل الفلاح والفوز. السعدي: ٨٥١.\nكيف تكون الوقاية من شح النفس سببًا للفلاح؟"],[547,"§الحشر\nwords\nغِلًاحَسَدًا، وَحِقدًا.\nلإِخوَانِهِمُيَهُودِ بَنِي النَّضِيرِ.\nجُدُرٍحِيطَانٍ.\nبَأسُهُم بَينَهُمعَدَاوَتُهُم فِيمَا بَينَهُم.\nشَتَّىمُتَفَرِّقَةٌ.\nوَبَالَ أَمرِهِمسُوءَ عَاقِبَةِ كُفرِهِم.\nكَمَثَلِ الشَّيطَانِمَثَلُ المُنَافِقِينَ فِي وَعدِهِمُ اليَهُودَ بِالنَّصرِ وَخِذلاَنِهِم لَهُم كَمَثَلِ الشَّيطَانِ.\ndeeds\nادع بهذا الدعاء.\nتعوذ بالله من الشيطان الرجيم ووساوسه.\nاستخرج من هذه الآيات ثلاثًا من صفات المنافقين.\nguid\nالحرص على تنقية القلب من الغل والحقد على أهل الإيمان.\nالخوف والجبن صفة ملازمة لليهود.\nالخوف من الخلق أكثر من الخالق علامة عدم الفهم.\nrefl\nوَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ١٠\nقيل: يعني من جاء بعد الصحابة؛ وهم التابعون ومن تبعهم إلى يوم القيامة؛ وعلى هذا حملها مالك فقال إن من قال في أحد الصحابة قول سوء فلا حظ له في الغنيمة والفيء؛ لأن الله وصف الذين جاؤوا بعد الصحابة بأنهم: ﴿يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ﴾؛ فمن قال ضدّ ذلك فقد خرج عن الذين وصفهم الله. ابن جزي: ٢/٤٣٠.\nكيف استنبط الإمام مالك من هذه الآية أن من تكلم في الصحابة بسوء لا حظ له في الفيء؟\nوَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ\nوهذا من فضائل الإيمان: أن المؤمنين ينتفع بعضهم ببعض، ويدعو بعضهم لبعض؛ بسبب المشاركة في الإيمان المقتضي لعقد الأخوة بين المؤمنين، التي من فروعها أن يدعو بعضهم لبعض. السعدي: ٨٥٢.\nاذكر فضيلة من فضائل الإيمان دلت عليها هذه الآية.\nلَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ١٣\nوإنَّما الفقه كل الفقه: أن يكون خوف الخالق ورجاؤه ومحبته مقدمة على غيرها، وغيرها تبعًا لها. السعدي: ٨٥٢.\nما علامة فقه العبد؟\nلَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ\nوجه وصف الرهبة بأنها في صدورهم: الإشارة إلى أنها رهبة جدُّ خفية، أي: أنهم يتظاهرون بالاستعداد لحرب المسلمين، ويتطاولون بالشجاعة؛ ليرهبهم المسلمون، وما هم بتلك المثابة، فأطلع اللهُ رسوله -صلى الله عليه وسلم- على دخيلتهم. ابن عاشور: ٢٨/١٠٣.\nلماذا وصفت الرهبة بأنها في صدورهم؟ وما الذي يفيده المسلمون من هذا الوصف؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ\nقال القشيري: \"اجتماع النفوس مع تنافر القلوب واختلافها أصل كل فساد، وموجب كل تخاذل، ومقتضٍ لتجاسر العدو. واتفاق القلوب والاشتراك في الهمة والتساوي في القصد يوجب كل ظفر وكل سعادة\". البقاعي: ١٩/٤٥٢.\nما خطورة تنافر القلوب؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ١٤\nلا دين لهم يجمعهم لعلمهم أنهم على الباطل؛ فهم أسرى الأهوية، والأهوية في غاية الاختلاف؛ فالعقل مدار الاجتماع كما أن الهوى مدار الاختلاف. البقاعي: ١٩/٤٥٣.\nما دلالة وصف اليهود بعدم العقل؟\nبَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ١٤\nوفي الآية تربية للمسلمين ليحذروا من التخالف والتدابر، ويعلموا أن الأمة لا تكون ذات بأس على أعدائها إلا إذا كانت متفقة الضمائر. ابن عاشور: ٢٨/١٠٦.\nفي الآية إشارة لأهمية الوحدة وعدم التفرق في مواجهة العدو؛ وضّح ذلك."],[548,"§الحشر\nwords\nوَلتَنظُروَلتَتَدَبَّر.\nفَأَنسَاهُم أَنفُسَهُمبِحَيثُ غَفَلُوا عَن حُظُوظِ أَنفُسِهِم فِي الآخِرَةِ.\nمُتَصَدِّعًامُتَشَقِّقًا.\nوَالشَّهَادَةِوَ عَالِمُ كُلِّ مُعلَنٍ، وَحَاضِرٍ.\nالمُؤمِنُالمُصَدِّقُ رُسُلَهُ بِالمُعجِزَاتِ، وَالآيَاتِ البَيِّنَاتِ.\ndeeds\nتأمل أعمالك في الأسبوع الماضي، واستخرج ثلاث عبادات عملتها، واحمد الله عليها، ثم استخرج ثلاثة أخطاء، واستغفر الله منها.\nاحرص هذا اليوم على أدعية الدخول والخروج من المنزل، وأذكار الصباح والمساء.\nادع الله تعالى بأسمائه الحسنى الواردة في هذه السورة.\nguid\nتذكر دائمًا يوم القيامة واجعله نصب عينيك.\nموجبات التقوى كثيرة؛ فمنها تذكر الآخرة، ومنها استشعار عظمة الله.\nاحرص على الخشوع عند قراءة القرآن.\nrefl\nوَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ\nمجيء (قدَّمت) بصيغة الماضي حث على الإسراع في العمل وعدم التأخير؛ لأنه لم يملك إلا ما قدم في الماضي، والمستقبل ليس بيده ولا يدري ما يكون فيه: ﴿وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗا﴾ [لقمان: ٣٤]. الشنقيطي: ٨/٥٤.\nما وجه مجيء (قدَّمت) بصيغة الماضي؟\nوَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ\nهذه الآية الكريمة أصل في محاسبة العبد نفسه، وأنه ينبغي له أن يتفقدها؛ فإن رأى زللًا تداركه بالإقلاع عنه والتوبة النصوح والإعراض عن الأسباب الموصلة إليه، وإن رأى نفسه مقصرًا في أمر من أوامر الله بذل جهده واستعان بربه في تكميله وتتميمه وإتقانه، ويقايس بين منن الله عليه وإحسانه وبين تقصيره؛ فإن ذلك يوجب له الحياء بلا محالة. السعدي: ٨٥٣.\nتحدث عن محاسبة النفس في ضوء هذه الآية.\nوَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ\nوأما إنساؤه نفسَه؛ فهو إنساؤه لحظوظها العالية، وأسباب سعادتها وفلاحها وصلاحها، وما تكمل به؛ ينسيه ذلك جميعه فلا يخطره بباله، ولا يجعله على ذكره، ولا يصرف إليه همته فيرغب فيه؛ فإنه لا يمر بباله حتى يقصده ويؤثره. وأيضًا فينسيه عيوب نفسه ونقصها وآفاتها فلا يخطر بباله إزالتها. ابن القيم: ٣/١٤٧.\nكيف ينسى العبد نفسه؟\nوَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ١٩\n(فأنساهم أنفسهم) كأن السامع سأل: ماذا كان أثر إنساء الله إياهم أنفسهم؟ فأجيب بأنهم بلغوا بسبب ذلك منتهى الفسق في الأعمال السيئة حتى حقّ عليهم أن يقال: إنه لا فسق بعد فسقهم. ابن عاشور: ٢٨/١١٤.\nما أثر إنساء الله إياهم أنفسهم؟\nلَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ\nحثَّ على تأمل مواعظ القرآن، وبيَّنَ أنه لا عذر في ترك التدبر؛ فإنه لو خوطب بهذا القرآن الجبال مع تركيب العقل فيها لانقادت لمواعظه، ولرأيتها على صلابتها ورزانتها خاشعة متصدعة -أي متشققة- من خشية الله. القرطبي: ٢٠/٣٨٨.\nهل لأحد عذر في ترك تدبر القرآن بعد هذا البيان؟\nهُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ ٢٢\nثم أعقبه بالدليل على إفراده تعالى بالألوهية بما لا يشاركه غيره فيه بقوله تعالى: ﴿عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ﴾. وهذا الدليل نص عليه على أنه دليل لوحدانية الله تعالى في مواضع أخرى. الشنقيطي: ٨/٦٨.\nما الدليل على إفراد الله تعالى بالألوهية؟\nهُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ\nوذِكرُ وصف (المؤمن) عقب الأوصاف التي قبله إتمامٌ للاحتراس من توهّم وصفه تعالى بـ(الملك) أنه كالملوك المعروفين بالنقائص؛ فأفيد أولًا نزاهة ذاته بوصف (القدوس)، ونزاهة تصرفاته المغيَّبة عن الغدر والكَيد بوصف (المؤمن)، ونزاهةُ تصرفاته الظاهرةِ عن الجور والظلم بوصف (السلام). ابن عاشور: ٢٨/١٢١.\nلماذا جاءت الأسماء الحسنى ﴿ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ﴾ بعد اسم الله تعالى (الملك)؟"],[549,"§الممتحنة\nwords\nأَولِيَاءَخُلَصَاءَ وَأَحِبَّاءَ.\nتُلقُونَتُفضُونَ.\nيَثقَفُوكُميَظفَرُوا بِكُم.\nوَيَبسُطُوايَمُدُّوا.\nيَفصِلُ بَينَكُميُفَرِّقُ بَينَ المُطِيعِينَ، وَالعَاصِينَ.\nأُسوَةٌقُدوَةٌ.\nأَنَبنَارَجَعنَا بِالتَّوبَةِ، وَالطَّاعَةِ.\nالمَصِيرُالمَرجِعُ.\ndeeds\nقل: \"ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا\".\nقل: \"ربنا عليك توكلنا، وإليك أنبنا، وإليك المصير\".\nادعُ بهذا الدعاء: \"ربنا لا تجعلنا فتنةً للذين كفروا، واغفر لنا ربنا؛ إنك أنت العزيز الحكيم\".\nguid\nالحذر من كيد الكفار وأساليبهم التي يريدون بها إضعاف انتماء المسلمين للإسلام.\nأولادك وأرحامك لن ينفعوك شيئًا إذا تركت أمر الله لأجلهم.\nالتوكل على الله وتفويض الأمر إليه.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ\nفإن المودة إذا حصلت تبعتها النصرة والموالاة؛ فخرج العبد من الإيمان، وصار من جملة أهل الكفران، وانفصل عن أهل الإيمان. السعدي: ٨٥٥.\nلماذا النهي عن مودة الكفار؟\nوَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡ\nفأيّ فائدة لإسراركم إن كنتم تعلمون أني عالم به، وإن كنتم تتوهمون أني لا أعلمه فهي القاصمة. البقاعي: ١٩/٤٨٨.\nما فائدة الإخبار بعلم الله بالإسرار والإعلان؟\nإِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ ٢\nالدين أعز على المؤمنين من أرواحهم لأنهم باذلون لها دونه، وأهم شيء عند العدو أن يقصد أهم شيء عند صاحبه. الألوسي: ١٤/٢٦٣.\nما أعز شيء عند المؤمنين؟ وما أهم شيء عند الكفار؟\nلَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ٣\nلما اعتذر حاطب بأن له أولادًا وأرحامًا فيما بينهم، بيَّن الرب -عز وجل- أن الأهل والأولاد لا ينفعون شيئًا يوم القيامة إن عُصي من أجل ذلك. القرطبي: ٢٠/٤٠٢.\nهل يعذر المسلم بالتجسس على المسلمين خوفًا على نفسه أو أولاده وأمواله؟\nقَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُ\nالحب في الله تعالى والبغض فيه سبحانه من أوثق عرى الإيمان، فلا ينبغي أن يُغفل عنهما. الألوسي: ١٤/٢٦٣.\nما أوثق عُرى الإيمان؟\nقَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُ\nأي أن يكون المسلمون تابعين لرضى رسولهم -صلى الله عليه وسلم- كما كان الذين مع إبراهيم -عليه السلام-. ابن عاشور: ٢٨/١٤٣.\nما دلالة الأمر بالاقتداء بإبراهيم -عليه السلام- والذين معه؟\nرَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ\nأي: لا تسلطهم علينا بذنوبنا فيفتنونا... ويفتنون أيضًا أنفسهم؛ فإنهم إذا رأوا لهم الغلبة ظنوا أنهم على الحق وأنَّا على الباطل، فازدادوا كفرًا وطغيانًا. السعدي: ٨٥٦.\nكيف يكون المسلم فتنةً للكافر؟"],[550,"§الممتحنة\nwords\nيَرجُو اللهَيَطمَعُ فِي الخَيرِ مِنَ اللهِ.\nيَتَوَلَّيُعرِض عَنِ الاِقتِدَاءِ بِالأَنبِيَاءِ، وَيُوَالِ أَعدَاءَ اللهِ.\nالحَمِيدُالمَحمُودُ فِي ذَاتِهِ، وَصِفَاتِهِ، وَأَفعَالِهِ.\nوَتُقسِطُواتَعدِلُوا فِيهِم.\nوَظَاهَرُواعَاوَنُوا.\nأَن تَوَلَّوهُمأَن تَنصُرُوهُم، وَتَوَدُّوهُم.\nفَامتَحِنُوهُنّفَاختَبِرُوهُنَّ؛ لِتَعلَمُوا صِدقَ إِيمَانِهِنَّ.\ndeeds\nادع الله تعالى أن يهدي أهل الضلال والكفر.\nأهد هدية لكافر تأليفًا لقلبه.\nتذكر مسلمًا أخطأت عليه ثم اعتذر منه أو ادع الله له.\nguid\nأهمية القدوة في حياة المسلم.\nجواز معاملة الكافر غير الحربي والإحسان إليه.\nالقسط والعدل مع الموالف والمخالف.\nrefl\nوَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ٦\n﴿وَمَن يَتَوَلَّ﴾ أي: عن الإسلام وقبول هذه المواعظ، ﴿فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ﴾ أي: لم يتعبدهم لحاجته إليهم، (الحميد) في نفسه وصفاته. القرطبي: ٢٠/٤٠٥.\nما مناسبة ختم الآية بهذين الاسمين لله تعالى؟\n۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم\nلما أمر الله المسلمين بعداوة الكفار ومقاطعتهم فامتثلوا ذلك على ما كان بينهم وبين الكفار من القرابة، فعلم الله صدقهم فآنسهم بهذه الآية، ووعدهم بأن يجعل بينهم مودة، وهذه المودة كملت في فتح مكة؛ فإنه أسلم حينئذ سائر قريش. ابن جزي: ٢/٤٣٦.\nما مناسبة هذه الآية بعد الحديث عن التبرؤ من الكافرين؟\n۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ\n﴿۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةًۚ﴾ سببها رجوعهم إلى الإيمان، ﴿وَٱللَّهُ قَدِيرٌۚ﴾ على كل شيء، ومن ذلك هداية القلوب، وتقليبها من حال إلى حال. السعدي: ٨٥٦.\nلماذا ذكر الله قدرته بعد أن ذكر أنه بالإمكان انتقال عداوة المشركين إلى المودة؟\nلَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ٨\nلما ذكر سبحانه ما ينبغي للمؤمنين من معاداة الكفار وترك موادتهم فصل القول فيمن يجوز بره منهم ومن لا يجوز فقال: (لا ينهاكم الله عن الذين لم يقاتلوكم في الدين...). الشوكاني: ٥/٢١٣.\nما مناسبة الآية لمَّا قبلها؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ\nقال القشيري: \"وفي الجملة الامتحان طريق إلى المعرفة، وجواهر النفس تتبين بالتجربة، ومن أقدم على شيء من غير تجربة يجني كأس الندم\". البقاعي: ١٩/٥١٤.\nما أهمية امتحان النفوس؟\nفَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ\nفيه دلالة على أن الإيمان يمكن الاطلاع عليه يقينًا. ابن كثير: ٤/٣٥١.\nهل يمكن الاطلاع اليقيني على إيمان بعض الناس؟\nفَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ\nأمر الله تعالى إذا أُمسِكَت المرأة المسلمة أن يُرَدَّ على زوجها ما أنفق، وذلك من الوفاء بالعهد؛ لأنه لمَّا مُنِع من أهله بحرمة الإسلام أَمَر برد المال إليه حتى لا يقع عليهم خسران من الوجهين: الزوجة والمال. القرطبي: ٢٠/٤١٤.\nاذكر صورة من صور الوفاء بالعهد في الآية."],[551,"§الصف ، الممتحنة\nwords\nيُبَايِعنَكَيُعَاهِدنَكَ.\nبِبُهتَانٍ يَفتَرِينَهُبِأَن يُلحِقنَ بِأَزوَاجِهِنَّ أَولاَدًا لَيسُوا مِنهُم.\nلاَ تَتَوَلَّوالاَ تَجعَلُوهُم أَولِيَاءَ، وَأَخِلاَّءَ.\nكَبُرَ مَقتًاعَظُمَ بُغضًا.\nمَرصُوصٌمُتَرَاصٌّ مُحكَمٌ لاَ فُرجَةَ فِيهِ، وَلاَ يَنفُذُ فِيهِ العَدُوُّ.\nزَاغُواعَدَلُوا عَنِ الحَقِّ، مَعَ عِلمِهِم بِهِ.\ndeeds\nسبح الله تعالى مائة مرة.\nحدد عملًا صالحًا وطبقه، ثم أرسل رسالة لزملائك تحثهم على هذا العمل حتى تكون من العاملين بما تقول.\nتذكر عالمًا أو داعية تعرض لإساءة واذكر محاسنه لأصحابك.\nguid\nلتكن حياتك منظمة؛ فالله يحب الذين يقاتلون في سبيله صفًّا، ويحب الذين يصفُّون في الصلاة.\nصبر الأنبياء على الأذى، وهم القدوة للدعاة.\nالحذر من الزيغ عن طاعة الله تعالى؛ فهو سبب لزيغ القلب.\nrefl\nوَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ\nومعصيته لا تكون إلا في معروف؛ فإنه لا يأمر بمنكر، لكن هذا قيل فيه دلالة على أن طاعة أولي الأمر إنَّما تلزم في المعروف. ابن تيمية: ٦/٢٩٥.\nالنبي -صلى الله عليه وسلم- لا يأمر إلا بالمعروف، فلماذا قيد النهي عن معصيته بالمعروف؟\nوَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ\nأي فيما تأمرهن به من معروف وتنهاهن عنه من منكر، والتقييد بالمعروف مع أن الرسول -صلّى الله تعالى عليه وسلم- لا يأمر إلا به؛ للتنبيه على أنه لا يجوز طاعة مخلوق في معصية الخالق. الألوسي: ١٤/٢٧٤.\nما فائدة التقييد بالمعروف مع أن الرسول -صلى الله عليه وسلم- لا يأمر إلا به؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ٢\nقال النخعي: \"ثلاث آيات منعتني أن أقص على الناس: ﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ﴾ [البقرة: ٤٤]، ﴿وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُ﴾ [هود: ٨٨]، ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ﴾\". القرطبي: ٢٠/٤٣٦.\nاذكر ما بلغ إليه حال السلف من الخوف من هذه الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ٢\nينبغي للآمر بالخير أن يكون أول الناس إليه مبادرة، وللناهي عن الشر أن يكون أبعد الناس منه. السعدي: ٨٥٨.\nما الذي يفيده المؤمن الداعية من هذه الآية؟\nإِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ٤\nوتكون صفوفهم على نظام وترتيب به تحصل المساواة بين المجاهدين، والتعاضد، وإرهاب العدو، وتنشيط بعضهم بعضًا. السعدي: ٨٥٨.\nما الحكمة من التراص وقت القتال صفًا كالبنيان المرصوص؟\nكَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ ٤\nقال قتادة: \"ألم تر إلى صاحب البنيان كيف لا يحب أن يختلف بنيانه؟ فكذلك الله -عز وجل- لا يحب أن يختلف أمره، وإن الله صف المؤمنين في قتالهم، وصفهم في صلاتهم، فعليكم بأمر الله؛ فإنه عصمة لمن أخذ به\". ابن كثير: ٤/٣٥٩.\nأمر الله المؤمنين بحسن التنظيم والترتيب في موضعين، ما هما؟\nفَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡ\nوهذه الآية الكريمة تفيد أن إضلال الله لعباده ليس ظلمًا منه، ولا حجة لهم عليه، وإنَّما ذلك بسبب منهم؛ فإنهم الذين أغلقوا على أنفسهم باب الهدى بعد ما عرفوه، فيجازيهم بعد ذلك بالإضلال والزيغ الذي لا حيلة لهم في دفعه. السعدي: ٨٥٩.\nفي الآية رد على من يحتج بانحرافه بالقدر؛ وضّح ذلك."],[552,"§الصف\nwords\nافتَرَىاختَلَقَ.\nنُورَ اللهِالحَقَّ الَّذِي جَاءَ بِهِ الرَّسُولُ -صلّى الله عليه وسلّم-.\nبِأَفوَاهِهِمبِأَقوَالِهِمُ الكَاذِبَةِ.\nمُتِمُّ نُورِهِمُظهِرٌ الحَقَّ بِإِتمَامِ دِينِهِ.\nالدِّينِ كُلِّهِالأَديَانِ المُخَالِفَةِ كُلِّهَا.\nلِلحَوَارِيِّينَأَصفِيَاءِ عِيسَى -عليه السلام-، وَخَوَاصِّهِ.\nظَاهِرِينَغَالِبِينَ.\ndeeds\nمن أنواع الجهاد: الجهاد بالمال في سبيل الخير وصلاح الأمة؛ فتصدق ببعض مالك على جهةٍ ترى أنها تعمل على الرفع من شأن الأمة.\nادع كافرًا للإسلام.\nادع الله تعالى أن يجعلك من أنصاره.\nguid\nالحذر من افتراء الكذب على الله -عز وجل-.\nعليك بالتجارة الرابحة.\nالتشبه بالأمم السابقة في الخير.\nrefl\nيُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ\nيحاولون أن يردوا الحق بالباطل، ومثلهم في ذلك كمثل من يريد أن يطفئ شعاع الشمس بفيه؛ وكما أن هذا مستحيل، كذلك ذاك مستحيل. ابن كثير: ٤/٣٦١.\nبيِّن الصورة التشبيهية التي تدل عليها هذه الآية.\nوَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ٨\nوجملة: ﴿وَٱللَّهُ مُتِمُّ نُورِهِۦ﴾ معطوفة على جملة (يريدون)؛ وهي إخبار بأنهم لا يبلغون مرادهم، وأن هذا الدِّين سيتم؛ أي يبلغ تمام الانتشار. ابن عاشور: ٢٨/١٩٠.\nما البشارة الواردة في قوله تعالى: ﴿وَٱللَّهُ مُتِمُّ نُورِهِۦ﴾؟\nهُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ٩\nمعلوم أن الله وعد بإظهاره على الدين كله: ظهور علم وبيان، وظهور سيف وسنان؛ فقال تعالى: ﴿هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ﴾. وقد فسر العلماء ظهورَه بهذا وهذا، ولفظ الظهور يتناولهم؛ فإن ظهور الهدى بالعلم والبيان، وظهور الدين باليد والعمل. ابن تيمية: ٦/٢٩٧.\nكيف يكون ظهور الدين على بقية الأديان؟\nتُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ١١\nفكأن النفوس ضَنَّت بحياتها وبقائها، فقال: ﴿ذَٰلِكُمۡ خَيۡرٌ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ﴾ يعني: أن الجهاد خير لكم من قعودكم للحياة والسلامة. ابن القيم: ٣/١٥٣.\nما وجه ختم الآية بقوله: ﴿إِن كُنتُمۡ تَعۡلَمُونَ﴾؟\nتُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ\nمن المعلوم أن الإيمان التام هو التصديق الجازم بما أمر الله بالتصديق به، المسلتزم لأعمال الجوارح. ومن أَجَلِّ أعمال الجوارح الجهاد في سبيل الله؛ فلهذا قال: ﴿وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ﴾. السعدي: ٨٦٠.\nقرنت الآية بين الإيمان والجهاد، فما العلاقة بينهما؟\nيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١٢\nوإنَّما خُصّت المساكن بالذكر هنا لأن في الجهاد مفارقة مساكنهم، فوعدوا على تلك المفارقة المؤقتة بمساكن أبدية. ابن عاشور: ٢٨/١٩٥.\nلماذا خص المساكن بالذكر؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ\nيقول تعالى آمرًا عباده المؤمنين أن يكونوا أنصار الله في جميع أحوالهم بأقوالهم وأفعالهم وأنفسهم وأموالهم. ابن كثير: ٤/٣٦١.\nهل نصرة الله تكون مقتصرة على زمن دون زمن؟ أو في جانب دون جانب؟"],[553,"§الجمعة\nwords\nيُسَبِّحُيُنَزِّهُ اللهَ عَن كُلِّ مَا لاَ يَلِيقُ بِهِ.\nالقُدُّوسِالمُنَزَّهِ عَن كُلِّ نَقصٍ.\nالعَزِيزِالقَوِيِّ الغَالِبِ الَّذِي لاَ يُغَالَبُ.\nالأُمِّيِّينَالعَرَبِ الَّذِينَ لاَ يَقرَؤُونَ، وَلاَ كِتَابَ عَندَهُم.\nلَمَّا يَلحَقُوا بِهِملَم يَجِيئُوا بَعدُ، وَسَيَجِيئُونَ.\nأَسفَارًاكُتُبًا.\nبِئسَ مَثَلُ القَومِقَبُحَ مَثَلُهُم.\ndeeds\nادع الله بأسمائه: (القدوس) (العزيز) (الحكيم)، وتعلم ما لها من آثار إيمانية عليك.\nاعمل عملًا بالسر لا يطلع عليه غيرك.\nسَلِ الله حسن الخاتمة.\nguid\nمهمة الداعية تربية الناس علمًا وعملًا بالكتاب والسنة.\nالعناية بتزكية النفس.\nسوء مثال من لم يعمل بعلمه.\nrefl\nيُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١\nهذه السورة جاء فيها فعل التسبيح مُضارعًا، وجيء به في سواها ماضيًا؛ لمناسبةٍ فيها وهي: أن الغرض منها التنويه بصلاة الجمعة والتنديد على نفر قطعوا عن صلاتهم وخرجوا لتجارة أو لهو؛ فمناسب أن يحكى تسبيح أهل السماوات والأرض بما فيه دلالة على استمرار تسبيحهم وتجدده تعريضًا بالذين لم يتموا صلاة الجمعة. ابن عاشور: ٢٨/٢٠٦.\nلماذا جاء فعل التسبيح: (يسبح) في سورة الجمعة مضارعًا، وجاء ماضيًا في سواها؟\nيُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ\nيخبر تعالى أنه يسبح له ما في السماوات وما في الأرض، أي: من جميع المخلوقات، ناطقها وجامدها. ابن كثير: ٤/٣٦٣.\nهل تسبيح المخلوقات لله مقتصر على الناطق منها؟\nهُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ٢\nوابتُدِئ بالتلاوة؛ لأن أول تبليغ الدعوة بإبلاغ الوحي، وثُنِّيَ بالتزكية؛ لأن ابتداء الدعوة بالتطهير من الرجس المعنوي -وهو الشرك وما يَعلق به من مساوئ الأعمال والطباع-، وعقَّب بذكر تعليمهم الكتاب؛ لأن الكتاب بعد إبلاغه إليهم تبين لهم مقاصده ومعانيه. ابن عاشور: ٢٨/٢٠٩.\nلماذا ابتدأت الجملة بالتلاوة ثم بالتزكية ثم تعليم الكتاب والحكمة؟\nهُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ ٢\nغاية الكتاب في قوة فهمه والعمل به؛ فهي العلم المزيَّن بالعمل، والعمل المتقن بالعلم -معقوله ومنقوله-؛ ليضعوا كل شيء منه في أحكم مواضعه، فلا يزيغوا عن الكتاب كما زاغ بنو إسرائيل، فيكون مثلهم كمثل الحمار يحمل أسفارًا. ولو لم يكن له -صلى الله عليه وسلم- معجزة إلا هذه لكانت غاية. البقاعي: ٢٠/٥١.\nمتى يفيد المسلم الإفادة التامة من القرآن الكريم؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥\nيقول تعالى ذامًا اليهود الذين أعطوا التوراة وحملوها للعمل بها ثم لم يعملوا بها؛ مثلهم في ذلك ﴿كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ﴾ أي: كمثل الحمار إذا حمل كتبًا لا يدري ما فيها، فهو يحملها حملًا حسيًا ولا يدري ما عليه، وكذلك هؤلاء في حملهم الكتاب الذي أوتوه: حفظوه لفظًا، ولم يتفهموه، ولا عملوا بمقتضاه. ابن كثير: ٤/٣٦٤.\nهل حافظ القرآن الذي لا يفهمه ولا يتدبره ولا يعمل به يعتبر من أهل القرآن؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ\nفهذا المثل وإن كان قد ضرب لليهود فهو متناول من حيث المعنى لمن حمل القرآن فترك العمل به، ولم يُؤَدِّ حَقَّه، ولم يرعه حق رعايته. القاسمي: ٩/٢٢٩.\nهل هذا المَثَلُ خاصٌّ بأهل التوراة؟\nمَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ\nقال ميمون بن مهران: \"الحمار لا يدري أسفر على ظهره أم زبل؛ فهكذا اليهود\". الشوكاني: ٥/٢٢٥.\nمن خلال قول ميمون، بيّن وجه تشبيه اليهود بالحمير."],[554,"§الجمعة ، المنافقون\nwords\nوَذَرُوااترُكُوا.\nانفَضُّوا إِلَيهَاتَفَرَّقُوا عَنكَ قَاصِدِينَ إِلَيهَا.\nفَطُبِعَخُتِمَ.\nكَأَنَّهُم خُشُبٌ مُسَنَّدَةٌكَأَنَّهُم لِخُلُوِّ قُلُوبِهِم مِنَ الإِيمَانِ، وَعُقُولِهِم مِنَ الفَهمِ: أَخشَابٌ مُلقَاةٌ عَلَى حَائِطٍ.\nكُلَّ صَيحَةٍ عَلَيهِمكُلَّ صَوتٍ عَالٍ وَاقِعًا عَلَيهِم؛ لِعِلمِهِم بِحَقِيقَةِ حَالِهِم، وَلِخَوفِهِم.\ndeeds\nأكثر من ذكر الله تعالى وتسبيحه وتهليله.\nإذا أذن المؤذن فاترك ما في يديك واتجه للمسجد مباشرة.\nبين لأهلك أو لأصحابك خطر المنافقين وأنهم أعداء للدين.\nguid\nكثرة ذكر الله تعالى سبيل الفلاح.\nمن سمات المنافقين الكذب.\nعدم الاغترار بالصور والأشكال، فالعبرة بالحقائق.\nrefl\nفَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ٩\nقلت: وإيثار ﴿ذِكۡرِ ٱللَّهِ﴾ هنا دون أن يقول: \"إلى الصلاة\"، كما قال: (فإذا قضيت الصلاة) لتتأتى إرادة الأمرين: الخطبة والصلاة. ابن عاشور: ٢٨/٢٢٥.\nما المقصود بذكر الله هنا؟\nفَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ\nكان عراك بن مالك -رضي الله عنه- إذا صلى الجمعة انصرف فوقف على باب المسجد فقال: \"اللهم إني أجبت دعوتك، وصليت فريضتك، وانتشرت كما أمرتني؛ فارزقني من فضلك وأنت خير الرازقين\". ابن كثير: ٤/٣٦٧.\nكيف امتثل عِراك بن مالك -رضي الله عنه- هذه الآية؟\nفَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ١٠\nلما كان الاشتغال في التجارة مظنة الغفلة عن ذكر الله، أمر الله بالإكثار من ذكره. السعدي: ٨٦٣.\nلماذا ختمت هذه الآية بالأمر بذكر الله بعد الأمر بالانتشار في الأرض وطلب الرزق؟\nوَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ ١١\nليس الصبر على طاعة الله مفوتًا للرزق؛ فإن الله خير الرازقين، فمن اتقى الله رزقه من حيث لا يحتسب. السعدي: ٨٦٣.\nفي الآية إشارة إلى أن تقوى الله من أسباب الرزق؛ وضّح ذلك.\nإِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ ١\nوإنَّما شهد عليهم بالكذب مع أن ظاهر قولهم حق؛ لأن بواطنهم تكذِّب ظواهرهم، لأن الأعمال بالنيات. الشنقيطي: ٨/ ١٨٨.\nلم شهد الله تعالى على هؤلاء المنافقين بالكذب؟\n۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ٤\nكانوا رجالًا أجمل شيء، كأنهم خشب مسندة، شبههم بخشب مسندة إلى الحائط لا يسمعون ولا يعقلون، أشباح بلا أرواح، وأجسام بلا أحلام، وقيل: شبههم بالخشب التي قد تآكلت؛ فهي مسندة بغيرها لا يعلم ما في بطنها. القرطبي: ٢٠/٥٠٠.\nما وجه تشبيههم بالخشب المسندة؟\nهُمُ ٱلۡعَدُوُّ\nفهؤلاء هم العدو على الحقيقة؛ لأن العدو البارز المتميز أهون من العدو الذي لا يُشعَر به، وهو مخادع ماكر؛ يزعم أنه ولي، وهو العدو المبين. السعدي: ٨٦٤.\nلماذا وصف الله المنافقين بأنهم الأعداء حقيقة؟"],[555,"§المنافقون\nwords\nلَوَّوا رُؤُوسَهُمعَطَفُوهَا إِعرَاضًا، وَاستِهزَاءً.\nيَصُدُّونَيُعرِضُونَ.\nيَنفَضُّوايَتَفَرَّقُوا عَنهُ.\nرَجَعنَامِن غَزوَةِ بَنِي المُصطَلِقِ.\nلاَ تُلهِكُملاَ تَشغَلكُم.\nلَولاَ أَخَّرتَنِيهَلاَّ أَمهَلتَنِي، وَأَخَّرتَ أَجَلِي.\nأَجَلُهَاوَقتُ مَوتِهَا.\ndeeds\nاحضر درسًا أو محاضرةً شرعيةً.\nاستغفر لنفسك وللمؤمنين والمؤمنات.\nتبرع في إحدى الجهات الخيرية لكفالة داعية أو طالب علم لتبتعد عن صفات المنافقين.\nguid\nالعزة لا تكون إلا بالله، فمن أرادها فليطلبها من مالكها.\nالأموال والأولاد قد تسبب البعد عن الله تعالى.\nالحرص على الخاتمة الحسنة.\nrefl\nوَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ ٧\nاستدراك قوله: ﴿وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ﴾ لرفع ما يتوهم من أنهم حين قالوا: ﴿لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ﴾ كانوا قالوه عن بصيرة ويقين بأن انقطاع إنفاقهم على الذين يلوذون برسول الله -صلى الله عليه وسلم- يقطع رزقهم، فينفضون عنه بناء على أن القدرة على الإِنفاق منحصرة فيهم لأنهم أهل الأموال؛ وقد غفلوا عن تعدد أسباب الغنى وأسباب الفقر. ابن عاشور: ٢٨/٢٤٨.\nما فائدة الاستدراك ب﴿وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ﴾؟\nوَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ ٨\nالناس يطلبون العز بأبواب الملوك، ولا يجدونه إلا في طاعة الله. كان الحسن البصري يقول: \"وإن هملجت بهم البراذين، وطقطقت بهم البغال؛ فإن ذل المعصية في رقابهم، أبى الله إلا أن يذل من عصاه\". ابن تيمية: ٦/٣١٢.\nأين تطلب العزة الحقيقية؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nلما ذكر سبحانه قبائح المنافقين رجع إلى خطاب المؤمنين مرغبًا لهم في ذكره فقال: (يا أيها الذين آمنوا لا تلهكم أموالكم ولا أولادكم عن ذكر الله) فحذرهم عن أخلاق المنافقين الذين ألهتهم أموالهم وأولادهم عن ذكر الله. الشوكاني: ٥/٢٣٣.\nما مناسبة الآية لمَّا قبلها؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nوخصَّ الأموال والأولاد بتوجه النهي عن الاشتغال بها اشتغالًا يلهي عن ذكر الله؛ لأن الأموال مما يكثر إقبال الناس على إنمائها والتفكير في اكتسابها بحيث تكون أوقات الشغل بها أكثر من أوقات الشغل بالأولاد، ولأنها كما تشغل عن ذكر الله بصرف الوقت في كسبها ونمائها تشغل عن ذكره أيضًا بالتذكير لكنزها بحيث ينسى ذكر ما دعا الله إليه من إنفاقها. ابن عاشور: ٢٨/٢٥١.\nلماذا خص الأموال والأولاد بالنهي عن الاشتغال بها؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ\nدوام الذكر سبب لدوام المحبة؛ فالذكر للقلب كالماء للزرع... لا حياة له إلا به. وهو أنواع: ذكره بأسمائه وصفاته، والثناء عليه بها. الثاني: تسبيحه وتحميده، وتكبيره وتهليله، وتمجيده؛ وهو الغالب من استعمال لفظ الذكر عند المتأخرين. الثالث: ذكره بأحكامه وأوامره ونواهيه؛ وهو ذكر أهل العلم... ومن أفضل ذكره: ذكره بكلامه... ومن ذكره سبحانه: دعاؤه واستغفاره والتضرع إليه. فهذه خمسة أنواع من الذكر. ابن القيم: ٣/١٥٧-١٥٨.\nبيِّن أهمية الذكر، واذكر أنواعه.\nوَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم\nيدل ذلك على أنه تعالى لم يكلف العباد من النفقة ما يعنتهم ويشق عليهم؛ بل أمرهم بإخراج جزء مما رزقهم الله الذي يسره لهم ويسر لهم أسبابه. السعدي: ٨٦٥.\nما الفائدة من حرف الجر (من) الدال على التبعيض في هذه الآية؟\nمِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ ١٠\nفكل مفرط يندم عند الاحتضار، ويسأل طول المدة -ولو شيئًا يسيرًا- ليستعتب ويستدرك ما فاته. ابن كثير: ٤/٣٧٣.\nهل الندم عند الاحتضار خاص بالكفار؟ وما الذي تستفيده من ذلك؟"],[556,"§التغابن\nwords\nيُسَبِّحُيُنَزِّهَ اللهَ عَمَّا لاَ يَلِيقُ بِهِ.\nالمَصِيرُالمَرجِعُ.\nوَبَالَ أَمرِهِمسُوءَ عَاقِبَةِ كُفرِهِم.\nوَتَوَلَّواأَعرَضُوا عَنِ الحَقِّ.\nوَالنُّورِالقُرآنِ.\nلِيَومِ الجَمعِيَومِ القِيَامَةِ الَّذِي يُحشَرُ فِيهِ الأَوَّلُونَ وَالآخِرُونَ.\nيَومُ التَّغَابُنِيَظهَرُ فِيهِ خَسَارَةُ الكُفَّارِ، وَغَبنُهُم، بِتَركِهِمُ الإِيمَانَ.\nيُكَفِّريَمحُ.\ndeeds\nقل: \"اللهم كما حسنت خلقي فحسن خلقي\".\nاقرأ في القرآن قصة قومٍ أهلكوا، واستخرج منها أسباب هلاكهم.\nسَلِ الله أن يجعل خير أيامك آخرها.\nguid\nالإيمان الجازم بما قضى الله و قدر على العباد.\nيلزم لمن آمن بالبعث أن يعمل ويستعد لذلك اليوم.\nمن أسماء يوم القيامة: ﴿يَوۡمُ ٱلتَّغَابُنِۗ﴾؛ لأن الناس فيه بين رابح وخاسر.\nrefl\nيُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ١\nوله حمد كل ما فيها من خلق؛ لأن جميع من في ذلك من الخلق لا يعرفون الخير إلا منه، وليس لهم رازق سواه، فله حمد جميعهم. الطبري: ٢٣/٤١٥.\nما وجه كون ما في السموات والأرض يحمده سبحانه؟\nخَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ٣\nقيل: جعلهم أحسن الحيوان كله وأبهاه صورة؛ بدليل أن الإنسان لا يتمنى أن تكون صورته على خلاف ما يرى من سائر الصور، ومن حسن صورته أنه خلق منتصبًا غير منكب. القرطبي: ٢١/٩.\nما المراد بقوله: ﴿وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ﴾؟\nوَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ٤\nفإذا كان عليمًا بذات الصدور، تعيَّن على العاقل البصير أن يحرص ويجتهد في حفظ باطنه من الأخلاق الرذيلة، واتصافه بالأخلاق الجميلة. السعدي: ٨٦٦.\nما الذي يفيده العاقل من معرفة أن الله عليم بذات الصدور؟\nأَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ٥\nشبه ما حلّ بهم من العذاب بشيء ذي طعم كريه يذوقه من حلّ به ويبتلعه؛ لأن الذوق باللسان أشد من اللمس باليد أو بالجلد. ابن عاشور: ٢٨/ ٢٦٨.\nلماذا عبر عما يحل بالكافر من العذاب بالذوق؟\nزَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ٧\nالعسير في متعارف الناس لا يعسر على الله، وقد قال في الآية الأخرى: ﴿هُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِ﴾ [الروم: ٢٧]. ابن عاشور: ٢٨/٢٧٢.\nلماذا أخبرت الآية عن البعث بأنه يسير؟\nيَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ\nوالمراد بالمغبون: من غبن في أهله ومنازله في الجنة؛ فيظهر يومئذ غبن كل كافر بترك الإيمان، وغبن كل مؤمن بتقصيره في الإحسان. الألوسي: ١٤/٣١٩.\nلماذا سمي يوم القيامة بيوم التغابن؟\nيَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ\n﴿يَوۡمُ ٱلتَّغَابُنِۗ﴾ يعني: يوم القيامة. والتغابن مستعار من تغابن الناس في التجارة؛ وذلك إذا فاز السعداء بالجنة؛ فكأنهم غبنوا الأشقياء في منازلهم التي كانوا ينزلون منها لو كانوا سعداء. ابن جزي: ٢/٤٥٢.\nكيف يقع الغبن يوم القيامة؟"],[557,"§التغابن\nwords\nبِإِذنِ اللهِبِقَضَائِهِ، وَقَدَرِهِ.\nيَهدِ قَلبَهُيُوَفِّقهُ لِلتَّسلِيمِ بِالقَضَاءِ، وَالصَّبرِ عَلَى المَقدُورِ.\nتَوَلَّيتُمأَعرَضتُم عَن طَاعَةِ الرَّسُولِ صلّى الله عليه وسلّم.\nفَليَتَوَكَّلِفَليَعتَمِد، وَليُفَوِّض.\nتَعفُواتَتَجَاوَزُوا عَن سَيِّئَاتِهِم.\nوَتَصفَحُواتُعرِضُوا عَنهَا.\ndeeds\nاجمع زوجتك وأولادك أو بعض إخوانك وتدارسوا آية من كتاب الله.\nاعف عن مسلم أخطأ عليك؛ لعل الله أن يغفر لك.\nتصدق بمال -ولو قليل- لتتقي فتنة المال.\nguid\nالرضا بالقضاء والقدر.\nالإيمان يثبت القلب عند وقوع المصيبة.\nمن اتقى الشح أفلح وفاز.\nrefl\nمَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُ\nوهذا عام لجميع المصائب... فجميع ما أصاب العباد فبقضاء الله وقدره... والشأن كل الشأن هل يقوم العبد بالوظيفة التي عليه في هذا المقام أم لا يقوم بها؟! فإن قام بها فله الثواب الجزيل والأجر الجميل في الدنيا والآخرة؛ فإذا آمن أنها من عند الله فرضي بذلك وسلم لأمره هدى الله قلبه فاطمأن ولم ينزعج عند المصائب. السعدي: ٨٦٧.\nإذا عرفت أن المصائب من عند الله، فما الأثر المترتب على ذلك؟\nوَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ١١\nعن ابن عباس قوله: ﴿وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ﴾ يعني: \"يهد قلبه لليقين، فيعلم أن ما أصابه لم يكن ليخطئه، وما أخطأه لم يكن ليصيبه\". الطبري: ٢٣/٤٢.\nما المراد بهداية قلب المؤمن بالله تعالى في الآية؟\nوَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ١٣\nفذِكرُ اسم الإيمان هاهنا دون سائر أسمائهم دليلٌ على استدعاء الإيمان للتوكل، وأن قوة التوكل وضعفه بحسب قوة الإيمان وضعفه، وكلما قوي إيمان العبد كان توكله أقوى، وإذا ضعف الإيمان ضعف التوكل، وإذا كان التوكل ضعيفًا فهو دليل على ضعف الإيمان ولا بد. ابن القيم: ٣/١٥٩.\nلماذا خاطب الله المؤمنين باسم الإيمان بعد أن أمرهم بالتوكل؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ\nقال القاضي أبو بكر ابن العربي: \"هذا يبين وجه العداوة؛ فإن العدو لم يكن عدوًا لذاته وإنَّما كان عدوا بفعله؛ فإذا فعل الزوج والولد فعل العدو كان عدوًا، ولا فعل أقبح من الحيلولة بين العبد وبين الطاعة\". القرطبي: ٥٢١/١٧.\nما وجه كون الزوج والولد عدوا للرجل ؟\nإِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ١٥\nقال ابن مسعود: \"لا يقولن أحدكم: اللهم إني أعوذ بك من الفتنة، فإنه ليس منكم أحد إلا وهو مشتمل على فتنة؛ لأن الله تعالى يقول: ﴿أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٌ﴾، فأيكم استعاذ فليستعذ بالله من مُضِلاَّت الفتن\". ابن القيم: ٣/١٦٠.\nما الدعاء الذي ينبغي أن يدعوَه الإنسان في الفتن؟\nفَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ\nيأمر تعالى بتقواه التي هي امتثال أوامره واجتناب نواهيه، ويقيد ذلك بالاستطاعة والقدرة، فهذه الآية تدل على أن كل واجب عجز عنه العبد أنه يسقط عنه، وأنه إذا قدر على بعض المأمور وعجز عن بعضه فإنه يأتي بما يقدر عليه، ويسقط عنه ما يعجز عنه. السعدي: ٨٦٨.\nما الذي تستفيده من تخصيص التقوى بالاستطاعة؟\nفَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ١٦ إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ ١٧\nوالمقصود: الاعتناء بفضل الإِنفاق المأمور به اهتمامًا مكررًا؛ فبعد أن جُعل خيرًا، جُعل سببَ الفلاح، وعُرف بأنه قرض من العبد لربّه؛ وكفى بهذا ترغيبًا وتلطفًا في الطلبِ إذ جُعل المنفق كأنه يعطي الله تعالى مالًا وذلك من معنى الإِحسان في معاملة العبد ربّه. ابن عاشور: ٢٨/٢٩٠.\nاذكر مرغبات الإنفاق الواردة في الآيات الكريمة."],[558,"§الطلاق\nwords\nفَطَلِّقُوهُنَّ لِعِدَّتِهِنَّمُستَقبِلاَتٍ لِعِدَّتِهِنَّ، أَي: فِي طُهرٍ لَم يَقَع فِيهِ جِمَاعٌ.\nوَأَقِيمُواأَدُّوا.\nبَالِغُ أَمرِهِمُنَفِّذٌ حُكمَهُ؛ لاَ يَفُوتُهُ شَيءٌ، وَلاَ يُعجِزُهُ مَطلُوبٌ.\nقَدرًاأَجَلًا يَنتَهِي إِلَيهِ.\nيَئِسنَانقَطَعَ رَجَاؤُهُنَّ؛ لِكِبَرِهِنَّ.\nارتَبتُمشَكَكتُم؛ فَلَم تَدرُوا مَا الحُكمُ فِيهِنَّ.\ndeeds\nحذر مسلمًا من التعدي على شرع الله.\nاحرص على أذكار الصباح والمساء لأنها من أسباب التوكل على الله.\nبين لأحد زملائك أن تقوى الله سبب الرزق وتكفير الذنوب ورفعة الدرجات متذكرًا قوله تعالى.\nguid\nالتأمل في المقاصد والمصالح الشرعية المترتبة على أحكام الطلاق.\nأهمية التعامل بالمعروف في جميع الأحوال؛ وخصوصًا مع الضعفاء.\nتقوى الله مخرج من كل ضائقة.\nrefl\nوَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ\nقوله: ﴿وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ﴾ تحذير من التساهل في أحكام الطلاق والعدة؛ ذلك أن أهل الجاهلية لم يكونوا يقيمون للنساء وزنًا، وكان قرابة المطلقات قلما يُدافعن عنهن، فتناسى الناس تلك الحقوق وغمصوها؛ فلذلك كانت هذه الآيات شديدة اللهجة في التحدّي، وعبر عن تلك الحقوق بالتقوى وبحدود الله. ولزيادة الحرص على التقوى أتبع اسم الجلالة بوصف (ربكم)؛ للتذكير بأنه حقيق بأن يُتقى غضبه. ابن عاشور: ٢٨/٢٩٨-٢٩٩.\nما فائدة ذكر التقوى بين أحكام الطلاق؟\nذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ٢\nوخص المؤمن بالله واليوم الآخر لأنه المنتفع بذلك دون غيره. الشوكاني: ٥/٢٤١.\nلماذا خص المؤمن بالموعظة دون غيره؟\nوَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ٢\nفمن لم يتق الله وقع في الشدائد والآصار والأغلال التي لا يقدر على التخلص منها والخروج من تبعتها، واعتبر ذلك بالطلاق؛ فإن العبد إذا لم يتق الله فيه بل أوقعه على الوجه المحرم -كالثلاث ونحوها- فإنه لا بد أن يندم ندامة لا يمكن استدراكها ولا الخروج منها. السعدي: ٨٧٠.\nمن لم يتق الله كيف تكون أحواله في الأزمات والضوائق؟\nوَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ٢\nعن ابن عباس: ﴿يَجۡعَل لَّهُۥ مَخۡرَجًا﴾: \"ينجيه من كل كرب في الدنيا والآخرة\"، وقيل: المخرج هو أن يقنعه الله بما رزقه... وقال الكلبي: \"...يجعل له مخرجًا من النار إلى الجنة\"... [وقال] الربيع بن خثيم: \"...من كل شيء ضاق على الناس\". القرطبي: ٢١/٤٢-٤٣.\nبيّن المراد بالمخرج في الآية.\nوَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ\nقال بعض العلماء: الرزق على نوعين: رزق مضمون لكل حي طول عمره؛ وهو الغذاء الذي تقوم به الحياة، وإليه الإشارة بقوله: ﴿وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا﴾ [هود: ٦]. ورزق موعود للمتقين خاصة؛ وهو المذكور في هذه الآية. ابن جزي: ٢/ ٤٥٦.\nيستفاد من هذه الآية أن الرزق نوعان، فما هما؟\nوَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا ٣\nفلما ذكر كفايته للمتوكل عليه، فربما أوهم ذلك تعجل الكفاية وقت التوكل؛ فعقبه بقوله: ﴿قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٍ قَدۡرًا﴾ أي: وقتًا لا يتعداه؛ فهو يسوقه إلى وقته الذي قَدَّرَه له، فلا يستعجل المتوكل ويقول: قد توكلت ودعوت فلم أر شيئًا ولم تحصل لي الكفاية. فالله بالغ أمره في وقته الذي قدر له. ابن القيم: ٣/١٦٥.\nلماذا ختمت الآية بقوله تعالى: ﴿قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٍ قَدۡرًا﴾؟\nذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا ٥\n﴿وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا﴾ يقول: ويجزل له الثواب على عمله ذلك وتقواه، ومن إعظامه له الأجر عليه أن يدخله جنته، فيخلده فيها. الطبري: ٢٣/٤٥٦.\nبيّن كيف يعظم الله تعالى الأجر لمن اتقاه."],[559,"§الطلاق\nwords\nمِن وُجدِكُمعَلَى قَدرِ وُسعِكُم وَطَاقَتِكُم.\nأُولاَتِذَوَاتِ.\nوَأتَمِرُواوَليَأمُر بَعضُكُم بَعضًا.\nبِمَعرُوفٍبِمَا عُرِفَ مِن سَمَاحَةٍ، وَطِيبِ نَفسٍ.\nتَعَاسَرتُمتَشَاحَحتُم فِي الإِرضَاعِ فَامتَنَعَ الأَبُ مِنَ الأُجرَةِ، وَالأُمُّ مِنَ الرَّضَاعِ.\nقُدِرَضُيِّقَ.\nعَتَتعَصَت وَتَجَبَّرَت.\nوَبَالَ أَمرِهَاسُوءَ عَاقِبَةِ عُتُوِّهِم وَكُفرِهِم.\ndeeds\nانهَ اليوم عن منكر.\nسَلِ الله الهدى والتقى.\nاتل على بعض إخوانك وأقاربك شيئًا من القرآن الكريم.\nguid\nالنهي عن المضارة والأذية.\nالتأمل في نزول العقوبات بمن طغى وتكبر.\nلا تعمل من الأعمال إلا ما تطيقه.\nrefl\nفَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ\n(بمعروف) ونكَّره سبحانه تحقيقًا على الأَمَة بالرضى بالمستطاع؛ وهو يكون مع الخلق بالإنصاف، ومع النفس بالخلاف، ومع الحق بالاعتراف. البقاعي: ٢٠/١٦١.\nلماذا نكَّر المعروف في الآية ؟\nوَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ ٦\nوالائتمار بمعروف يشعر بأن للعرف دخلًا في ذلك، كما هو تنبيه صريح بأن لا يضار أحد الوالدين بولده، وأن تكون المفاهمة بين الزوجين بعد الفرقة في جميع الأمور -سواء في خصوص الرضاع أو غيره- مبناها على المعروف والتسامح والإحسان؛ وفاء لحق العشرة السابقة، ولا تنسوا الفضل بينكم. الشنقيطي: ٨/٢١٦.\nللإسلام أدب بعد الطلاق فما هو؟\nلِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا ٧\n﴿لِيُنفِقۡ ذُو سَعَةٍ مِّن سَعَتِهِۦۖ﴾ أمر بأن ينفق كل واحد على مقدار حاله، ولا يكلف الزوح ما لا يطيق، ولا تُضيَّع الزوجة، بل يكون الحال معتدلًا. وفي الآية دليل على أن النفقة تختلف باختلاف أحوال الناس. ابن جزي: ٢/٤٥٩.\nفي هذه الآية مظهر من مظاهر التيسير ورفع الحرج؛ بيّنه.\nوَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا ٨ فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا ٩\nفإن من زرع الشوك لا يجني الورد، ومن أضاع حق الله لا يُطاع في حظ نفسه، ومن احترق بمخالفة أمر الله تعالى فليصبر على مقاساة عقوبة الله تعالى. البقاعي: ٢٠/١٦٧.\nما عقاب القرية أو المجتمع إذا عتى عن أمر ربه؟\nوَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا ٨ فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا ٩\nأي حاسبنا أهلها قيل: يعني الحساب في الآخرة، وكذلك العذاب المذكور بعده. وقيل: يعني في الدنيا، وهذا أرجح؛ لأنه ذكر عذاب الآخرة بعد ذلك في قوله: ﴿أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابًا شَدِيدًاۖ﴾، أو لأن قوله: (فَحَاسَبنَاهَا)، (وَعَذَّبنَاهَا) بلفظ الماضي...، فمعنى حاسبناها؛ أي آخذناهم بذنوبهم ولم يُغتفر لهم شيء من صغائرها، و\"العذاب\" هو عقابهم في الدنيا، و\"النكر\" هو الشديد الذي لم يُعهد مثله. ابن جزي: ٢/٤٥٩.\nمتى يكون عذاب القرى العاصية؟\nفَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ\nأي: يا ذوي العقول التي تفهم عن الله آياته وعبره، وأن الذي أهلك القرون الماضية بتكذيبهم؛ أن من بعدهم مثلهم، لا فرق بين الطائفتين. السعدي: ٨٧٢.\nما وجه ذكر التقوى بعد ذكر قصة القرية التي عذبت؟\nٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ\nقال أهل المعاني: هو ما يدبر فيهن من عجيب تدبيره؛ فينزل المطر ويخرج النبات، ويأتي بالليل والنهار والصيف والشتاء، ويخلق الحيوان على اختلاف هيئاتها وينقلها من حال إلى حال. البغوي: ٤/٤٢٢.\nما المراد بقوله: ﴿يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ﴾؟"],[560,"§التحريم\nwords\nتَحِلَّةَ أَيمَانِكُمتَحلِيلَ أَيمَانِكُم بِأَدَاءِ الكَفَّارَةِ عَنهَا.\nمَولاَكُمنَاصِرُكُم، وَمُتَوَلِّي أُمُورِكُم.\nبَعضِ أَزوَاجِهِهِيَ: حَفصَةُ بِنتُ عُمَرَ -رضي الله عنهما-.\nوَأَظهَرَهُأَطلَعَهُ.\nعَرَّفَ بَعضَهُأَعلَمَ حَفصَةَ -رضي الله عنها- بَعضَ مَا أَخبَرَت بِهِ.\nصَغَت قُلُوبُكُمَامَالَت إِلَى مَحَبَّةِ مَا كَرِهَهُ الرَّسُولُ -صلّى الله عليه وسلّم- مِن إِفشَاءِ سِرِّهِ.\nسَائِحَاتٍصَائِمَاتٍ.\ndeeds\nاكتب مقالًا أو رسالة تبين فيها أنّ المعاصي هي سبب المشكلات الأسرية.\nصم يومًا في سبيل الله.\nقدم نصيحة لأهلك برسالة تبتغي بها وقايتهم من عذاب جهنم.\nguid\nإذا عاتبت أحدًا فلا تواجهه بكل ما اقترف حتى لا توقعه في اليأس.\nتكريم النبي -صلى الله عليه وسلم- وتشريفه ورعاية الله له.\nالتغافل عن بعض زلات إخوانك دليل على كريم طبعك.\nrefl\nقَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ٢\n(العَلِيمُ) فيعلم ما يصلحكم؛ فيشرعه سبحانه لكم، (الحَكِيمُ) المتقن أفعاله وأحكامه؛ فلا يأمركم ولا ينهاكم إلا حسبما تقتضيه الحكمة. الألوسي: ١٤/٣٤٥.\nما دلالة اسم الله (العليم) واسمه (الحكيم) في ختام الآية؟\nوَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا\nواستُدِل بالآية على أنه لا بأس بإسرار بعض الحديث إلى من يركن إليه من زوجة أو صديق، وأنه يلزمه كتمه. الألوسي: ١٤/٣٤٦.\nما حكم الإسرار ببعض الحديث إذا كان في معروف؟\nوَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ\nالكف عن بعض العتب أبعث على حياء المعتوب، وأعون على توبته وعدم عودته إلى فعل مثله. ﴿وَأَعۡرَضَ عَنۢ بَعۡضٍۖ﴾ وهو أمر السُّرِّيَّة والعسل؛ تكرمًا منه أن يستقصي في العتاب، وحياء وحسن عشرة. قال الحسن: \"ما استقصى كريم قط\". وقال سفيان الثوري: \"ما زال التغافل من فعل الكبراء\". البقاعي: ٢٠/١٨٦.\nما الفائدة المستنبطة من قوله تعالى: ﴿عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٍۖ﴾؟\nوَأَعۡرَضَ عَنۢ بَعۡضٖۖ\nوإعراض الرسول -صلى الله عليه وسلم- عن تعريف زوجه ببعض الحديث الذي أفشته من كرم خلقه؛ قال سفيان: \"ما زَال التغافل من فعل الكرام\"، وقال الحسن: \"ما استقصى كريمٌ قط\"، وما زاد على المقصود يَقلِب العتاب من عتاب إلى تقريع. ابن عاشور: ٢٨/٣٥٣.\nالتغافل أحيانًا من صفات الكرام، بين ذلك من قوله تعالى: ﴿وَأَعۡرَضَ عَنۢ بَعۡضٍۖ﴾.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا\nعن ابن عباس -رضي الله عنهما-: \"أي بالانتهاء عما نهاكم الله تعالى عنه، والعمل بطاعته\"... يعني: مروهم بالخير، وانهوهم عن الشر وعلموهم وأدبوهم. البغوي: ٤/٤٣٠.\nكيف تكون وقاية النفس والأهل من نار جهنم؟\nنَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ ٦\nوصف الله النار بهذه الأوصاف ليزجر عباده عن التهاون بأمره. السعدي: ٨٧٤.\nلماذا وصف الله النار بهذه الأوصاف؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ ٦ يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ٧\nولما كان النبي -صلى الله عليه وسلم- أعظم من أريد بأمر الأمة بالتأدب معه، فكان تعمد الإخلال بالأدب معه كفرًا؛ عُلِم أن هذه النار لأولئك، فعُلِم أن التقدير: يقولون: (يا أيها الذين كفروا) أي بالإخلال بالأدب في النبي -صلى الله عليه وسلم-؛ فأداهم ذلك إلى الإخلال بالأدب مع الله وبالأدب مع سائر خلقه. البقاعي: ٢٠/١٩٩.\nما حكم سوء الأدب مع رسول الله -صلى الله عليه وسلم-؟"],[561,"§التحريم\nwords\nتَوبَةً نَصُوحًاصَادِقَةً لاَ يَعُودُ صَاحِبُهَا إِلَى الذَّنبِ، وَلاَ يُرِيدُ العَودَ إِلَيهِ.\nلاَ يُخزِيلاَ يُذِلُّ، وَلاَ يُعَذِّبُ.\nوَاغلُظ عَلَيهِماستَعمِلِ الخُشُونَةَ وَالشِّدَّةَ فِي جِهَادِهِم.\nفَخَانَتَاهُمَابِالكُفرِ، وَالمُخَالَفَةِ فِي الدِّينِ.\nأَحصَنَتحَفِظَت وَصَانَت عَنِ الزِّنَى.\nالقَانِتِينَالمُطِيعِينَ لِرَبِّهِم.\ndeeds\nسَلِ الله أن يتوب عليك توبة نصوحًا.\nادع الله أن يجعل في قلبك نورًا ويغفر لك.\nصلِ ركعتين نافلة وأطل فيهما.\nguid\nبذل الجهد في جهاد الكفار والمنافقين والإغلاظ عليهم كما أمر الله تعالى.\nلا يغني عن العبد قربه من الصالحين حتى يكون صالحًا في نفسه.\nالحرص على الدعاء عند نزول البلاء.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا\nقال القرظي: \"يجمعها أربعة أشياء: الاستغفار باللسان، والإقلاع بالأبدان، وإضمار ترك العود بالجنان، ومهاجرة سيئ الإخوان\". البغوي: ٤/٤٣٠-٤٣١.\nما التوبة النصوح؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ\nومعلوم أن المنافقين كافرون، فكان جهاده -صلى الله عليه وسلم- للكفار بالسيف، ومع المنافقين بالقرآن؛ كما جاء عنه -صلى الله عليه وسلم- في عدم قتلهم: «لئلَّا يتحدث الناس أن محمدًا يقتل أصحابه»، ولكن كان جهادهم بالقرآن لا يقل شدة عليهم من السيف؛ لأنهم أصبحوا في خوف وذعر؛ يحسبون كل صيحة عليهم، وأصبحت قلوبهم خاوية كأنهم خشب مسندة؛ وهذا أشد عليهم من الملاقاة بالسيف، والعلم عند الله تعالى. الشنقيطي: ٨/٢٢٣.\nبيِّن الفرق بين جهاد الكفار وجهاد المنافقين.\nضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ ١٠\nضرب هذا المثل تنبيهًا على أنه لا يغني أحد في الآخرة عن قريب ولا نسيب إذا فرق بينهما الدين. القرطبي: ٢١/١٠٢.\nما المقصد من ضرب هذا المثل؟\nوَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ\nقال العلماء: \"اختارت الجار قبل الدار\". ابن كثير: ٤/٣٩٤.\nلماذا قدمت امرأة فرعون (عندك) على (بيتًا)؟\nوَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ١١\nفي الآية دليل على أن الاستعاذة بالله تعالى والالتجاء إليه -عز وجل- ومسألة الخلاص منه تعالى عند المحن والنوازل من سير الصالحين وسنن الأنبياء؛ وهو في القرآن كثير. الألوسي: ١٤/٣٥٨.\nفي الآية صفة من صفات الصالحين؛ فما هي؟"],[562,"§الملك\nwords\nطِبَاقًابَعضُهَا فَوقَ بَعضٍ، مِن غَيرِ مُمَاسَّةٍ.\nفُطُورٍشُقُوقٍ، وَصُدُوعٍ.\nخَاسِئًاذَلِيلًا صَاغِرًا.\nحَسِيرٌمُتعَبٌ، كَلِيلٌ.\nرُجُومًا لِلشَّيَاطِينِشُهُبًا مُحرِقَةً لِمُستَرِقِي السَّمعِ مِنَ الشَّيَاطِينِ.\nشَهِيقًاصَوتًا مُنكَرًا.\ndeeds\nقل: \"اللهم اجعل عملي خالصًا صوابًا\"، ثم تحرّ السنة في كل ما تعمله.\nتأمل في خلق النجوم ثم احمد الله على أن منع الشياطين من استراق السمع لئلَّا يفتنوا الخلق.\nقل: \"اللهم إني أسألك خشيتك في الغيب والشهادة\".\nguid\nالحث على قراءة سورة الملك كل ليلة.\nتعظيم الله -جل وعلا- في كل أمر من الأمور.\nعقوبة مخالفة الأنبياء وما أعد الله لمخالفيهم من العذاب والتوبيخ.\nrefl\nتَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ١\nإليه كل تدبير، وبقدرته إظهار ما يريد، لا مانع له من شيء، ولا كفؤ له بوجه. البقاعي:٢٠/٢١٧\nلماذا تطمئن القلوب بالاتكال على الله؟\nٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ ٢\nقال فضيل بن عياض: \"أخلصه وأصوبه\"... والعمل لا يقبل حتى يكون خالصًا صوابًا. البغوي: ٤/٤٣٥.\nما المراد بحسن العمل؟\nثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ ٤\nوإنَّما أمر بالنظر مرتين؛ لأن الإنسان إذا نظر في الشيء مرة لا يرى عيبه ما لم ينظر إليه مرة أخرى. القرطبي: ٢١/ ١١٦.\nلماذا أمر بإعادة النظر في السماوات؟\nوَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ ٥\nقال قتادة: \"خلق الله النجوم لثلاثة أشياء: زينة السماء، ورجوم الشياطين، ويُهتَدى بها في ظلمات البر والبحر\". ابن جزي: ٢/ ٤٩٤.\nعدِّد فوائد النجوم.\nتَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ ٨\nهذه الآية تدل على أن الله تعالى لا يعذب بالنار أحدًا إلا بعد أن ينذره في الدنيا. الشنقيطي: ٨/٢٣٣.\nما الذي يدل عليه سؤال خزنة النار لأفواج جهنم: ﴿أَلَمۡ يَأۡتِكُمۡ نَذِيرٌ﴾؟\nوَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ ١٠\nووجه تقديم السمع على العقل... لأن سمع دعوة النذير هو أول ما يتلقاه المنذَرون، ثم يُعمِلون عقولهم في التدبر فيها. ابن عاشور: ٢٩/٢٨.\nلماذا قدم السمع على العقل؟\nإِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ١٢\nوقدم المغفرة تطمينًا لقلوبهم؛ لأنهم يخشون المؤاخذة على ما فرط منهم من الكفر قبل الإسلام ومن اللمم ونحوه، ثم أعقبت بالبشارة بالأجر العظيم؛ فكان الكلام جاريًا على قانون تقديم التخلية على التحلية. ابن عاشور:٢٩/٢٩.\nلماذا قدمت المغفرة على الأجر الكبير في الآية؟"],[563,"§الملك\nwords\nذَلُولًاسَهلَةً، مُمَهَّدَةً تَستَقِرُّونَ عَلَيهَا.\nمَنَاكِبِهَانَوَاحِيهَا، وَجَوَانِبِهَا.\nتَمُورُتَضطَرِبُ بِكُم حَتَّى تَهلِكُوا.\nحَاصِبًارِيحًا تَرجُمُكُم بِالحِجَارَةِ الصَّغِيرَةِ.\nلَجُّوااستَمَرُّوا، وَتَمَادَوا.\nوَنُفُورشُرُودٍ وَتَبَاعُدٍ عَنِ الحَقِّ.\ndeeds\nتأمل كيف جعل الله هذه الأرض مذللة تمشي عليها، ثم اشكر الله تعالى على هذه النعم.\nتعرف على قدرة الله بالتأمل في الطيور وعدم سقوطها، ثم قل: \"سبحان من أعطى كل شيء خلقه ثم هدى\".\nقل: \"اللهم متعنا بأسماعنا وأبصارنا وقواتنا\"، واشكر الله عليها.\nguid\nلا يستوي طريق الحق وطريق الباطل.\nالمؤمن ليس مسؤولًا عن وقت يوم القيامة، وإنَّما عن الاستعداد له.\nتفويض العلم إلى الله.\nrefl\nوَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ١٣\nأي: بما فيها من النيات والإرادات؛ فكيف بالأقوال والأفعال التي تسمع وترى؟! السعدي: ٨٧٦.\nما وجه اختتام الآية بوصف الله بأنه عليم بذات الصدور؟\nأَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ١٤\nثم ختم الحجة باسمين مقتضيين لثبوتهما، وهما: (اللطيف)؛ الذي لطُف صنعه وحكمته ودقَّ حتى عجزت عنه الأفهام. و(الخبير)؛ الذي انتهى علمه إلى الإحاطة ببواطن الأشياء وخفاياها كما أحاط بظواهرها. فكيف تخفى على اللطيف الخبير ما تحويه الضمائر وتخفيه الصدور؟! ابن القيم: ٣/١٧٣.\nلماذا ختمت الآية باسمي (اللطيف) و(الخبير) لله عز وجل؟\nهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ ١٥\nواعلموا أن سعيكم لا يجدي عليكم شيئًا إلا أن ييسره الله لكم؛ ولهذا قال تعالى: ﴿وَكُلُواْ مِن رِّزۡقِهِۦۖ﴾؛ فالسعي لا ينافي التوكل. ابن كثير: ٤/٣٩٨.\nما الذي تدل عليه إضافة الرزق إلى الضمير العائد إلى الله -سبحانه وتعالى-؟\nهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ ١٥\nثم نَبَّه بقوله: ﴿وَإِلَيۡهِ ٱلنُّشُورُ﴾ على أَنَّا في هذا المسكن غير مستوطنين ولا مقيمين، بل دخلناه عابري سبيل، فلا يحسن أن نتخذه وطنًا ومستقرًا، وإنَّما دخلناه لنتزود منه إلى دار القرار؛ فهو منزل عبور لا مستقر حبور، ومعبر وممر لا وطن ومستقر. ابن القيم: ٣/١٧٤.\nأمرتنا الآية بالاستفادة مما في هذه الأرض ثم خُتِمَت بذكر النشور؛ فلماذا؟\nءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ ١٦\nوقدم التهديد بالخسف على التهديد بالحاصب؛ لأن الخسف من أحوال الأرض، والكلام على أحوالها أقرب هنا، فسُلك شبه طريق النشر المعكوس، ولأن إرسال الحاصب عليهم جزاء على كفرهم بنعمة الله التي منها رزقهم في الأرض المشار إليه بقوله: ﴿وَكُلُواْ مِن رِّزۡقِهِۦۖ﴾؛ فإن منشأ الأرزاق الأرضية من غيوث السماء؛ قال تعالى: ﴿وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ﴾ [ الذاريات: ٢٢]. ابن عاشور: ٢٩/٣٦.\nلماذا قدم التهديد بالخسف على التهديد بالحاصب؟\nأَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٢٢\nضرب الله مثلًا للمؤمن والكافر: (مكبًّا) أي: منكسًا رأسه؛ لا ينظر أمامه ولا يمينه ولا شماله؛ فهو لا يأمن من العثور والانكباب على وجهه، كمن ﴿يَمۡشِي سَوِيًّا﴾ معتدلًا ناظرًا ما بين يديه وعن يمينه وعن شماله. القرطبي: ٢١/١٢٩.\nلمن ضرب الله هذا المثل؟\nقُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ٢٣\n﴿قَلِيلًا مَّا تَشۡكُرُونَ﴾ أي: قلما تستعملون هذه القوى التي أنعم الله بها عليكم في طاعته وامتثال أوامره. ابن كثير: ٤/٣٩٩.\nما الذي يدل عليه ختم الآية بقوله: ﴿قَلِيلًا مَّا تَشۡكُرُونَ﴾؟"],[564,"§الملك ، القلم\nwords\nرَأَوهُ زُلفَةًرَأَوا عَذَابَ اللهِ قَرِيبًا.\nتَدَّعُونَتَطلُبُونَ أَن يُعَجَّلَ لَكُم مِنَ العَذَابِ استِهزَاءً.\nيُجِيرُيَحمِي.\nغَورًاذَاهِبًا فِي الأَرضِ لاَ تَصِلُونَ إِلَيهِ بِوَسِيلَةٍ.\nمَمنُونٍمَنقُوصٍ، وَلاَ مُنقَطِعٍ.\nتُدهِنُتُلاَيِنُ وَتُصَانِعُ.\nهَمَّازٍمُغتَابٍ لِلنَّاسِ.\nعُتُلٍّفَاحِشٍ، لَئِيمٍ، غَلِيظٍ فِي كُفرِهِ.\nزَنِيمٍمَنسُوبٍ لِغَيرِ أَبِيهِ.\ndeeds\nسَلِ الله أن ينزل الغيث.\nاحمد الله على ثلاث نعم أنعم بها عليك.\nقل: \"اللهم اهدني لأحسن الأخلاق\".\nguid\nالحث على مكارم الأخلاق.\nالوعيد لكل مكذب معرض مستهزئ.\nالتحذير من المداهنة في دين الله تعالى.\nrefl\nءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ\nالإيمان يشمل التصديق الباطن، والأعمال الباطنة والظاهرة. ولما كانت الأعمال وجودها وكمالها متوقفةً على التوكل، خص الله التوكل من بين سائر الأعمال، وإلا فهو داخل في الإيمان ومن جملة لوازمه. السعدي: ٨٧٨.\nالتوكل داخل في الإيمان، فلماذا خصه الله بالذكر من بين سائر الأعمال؟\nقُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ ٢٩\n(وعليه) أي: وحده. (توكلنا): لأنه لا شيء في يد غيره، وإلا لرحم من يريد عذابه أو عذب من يريد رحمته؛ فكل ما جرى على أيدي خلقه من رحمة أو نقمة فهو الذي أجراه. البقاعي: ٢٠/٢٧٠.\nلماذا نتوكل على الله وحده دون غيره؟\nنٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ ١\nالقسم بالقلم لشرفه بأنه يُكتب به القرآن، وكتبت به الكتب المقدسة، وتكتب به كتب التربية ومكارم الأخلاق والعلوم؛ وكل ذلك مما له حظ شرف عند الله تعالى. ابن عاشور: ٢٩/٦٠.\nلماذا أقسم الله تعالى بالقلم؟\nإِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ٧\nهذا فيه تهديد للضالين، ووعد للمهتدين. السعدي: ٨٧٩.\nماذا يفيد ذكر علمه سبحانه بالضالين والمهتدين؟\nفَلَا تُطِعِ ٱلۡمُكَذِّبِينَ ٨\nالنهي عن طاعة المرء نهيٌ عن التشبه به بالأولى؛ فلا يُطاع المكذب والحلاف، ولا يعمل بمثل عملهما. ابن تيمية: ٦/٣٧٠.\nدلت الآية على النهي عن التشبه بأهل الفسق والفجور؛ وضِّح ذلك.\nفَلَا تُطِعِ ٱلۡمُكَذِّبِينَ ٨ وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ ٩ وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ ١٠ هَمَّازٖ مَّشَّآءِۢ بِنَمِيمٖ ١١ مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ ١٢ عُتُلِّۢ بَعۡدَ ذَٰلِكَ زَنِيمٍ ١٣\nالأخلاق مكتسبة بالمعاشرة، ففيه تحذير عن اكتساب شيء من أخلاقهم بالمخالطة لهم؛ فليأخذ حذره؛ فإنه محتاج إلى مخالطتهم لأجل دعوتهم إلى الله تعالى. ابن تيمية: ٦/٣٧٠.\nيترتب على دعوة أهل المعاصي الانتباه إلى محذور؛ فما هو؟\nوَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ ١٠\nوذلك أن الكاذب -لضعفه ومهانته- إنَّما يتقي بأيمانه الكاذبة؛ التي يجترئ بها على أسماء الله تعالى، واستعمالها في كل وقت في غير محلها. ابن كثير: ٤/٤٠٤.\nلماذا نهينا عن اتباع الذي يكثر من الحلف؟"],[565,"§القلم\nwords\nبَلَونَاهُماختَبَرنَاهُم.\nلَيَصرِمُنَّهَالَيَقطَعُنَّ ثِمَارَ حَدِيقَتِهَا.\nفَطَافَعَلَيهَا أَحَاطَ نَازِلًا عَلَيهَا.\nطَائِفٌنَارٌ أَحرَقَتهَا.\nكَالصَّرِيمِكَاللَّيلِ المُظلِمِ.\nصَارِمِينَمُصِرِّينَ عَلَى قَطعِ الثِّمَارِ.\nعَلَى حَردٍعَلَى قَصدِهِمُ السَّيِّئِ فِي مَنعِ المَسَاكِينِ.\nرَاغِبُونَطَالِبُونَ الخَيرَ.\nتَخَيَّرُونَتَشتَهُونَ.\nزَعِيمٌكَفِيلٌ وَضَامِنٌ بِأَن يَكُونَ لَهُم ذَلِكَ.\ndeeds\nتصدق على أحد المساكين.\nقل: \"لا إله إلا أنت سبحانك إني كنت من الظالمين\".\nصل ركعتين وأطل فيها السجود، وادع الله أن يحسن وقوفك بين يديه.\nguid\nالدنيا دار ابتلاء وامتحان.\nالاعتراف بالذنب أول طريق النجاة.\nاستشعار عظيم العذاب للمكذبين وعظيم النعيم للمتقين.\nrefl\nإِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ\nإنا بلونا هؤلاء المكذبين بالخير، وأمهلناهم، وأمددناهم بما شئنا من مال وولد وطول عمر، ونحو ذلك مما يوافق أهواءهم، لا لكرامتهم علينا، بل ربما يكون استدراجًا لهم من حيث لا يشعرون.\nهل الغنى والفقر دليل على حب الله للعبد الغني وبغضه للعبد الفقير؟\nفَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ ١٩\nوعُجل العقاب لهم قبل التلبس بمنع الصدقة؛ لأن عزمهم على المنع وتقاسمهم عليه حقق أنهم مانعون صدقاتهم فكانوا مانعين. ويؤخذ من الآية موعظة للذين لا يواسون بأموالهم. ابن عاشور: ٢٩/٨٢.\nلماذا عجل عقاب أصحاب الجنة بمجرد عزمهم وقبل التلبس بمنع الصدقة؟\nوَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ ٢٥\nعزموا على منع المساكين، وطلبوا حرمانهم ونكدهم وهم قادرون على نفعهم؛ فغدوا بحال لا يقدرون فيها إلا على المنع والحرمان. الألوسي: ١٥/٣٦.\nما الذي عجل بحرمان أهل الجنة المذكورة في الآية من جنتهم؟\nبَلۡ نَحۡنُ مَحۡرُومُونَ ٢٧\nحرمنا خيرها ونفعها بمنعنا المساكين وتَركِنا الاستثناء. البغوي: ٤/٤٥١.\nما سبب حرمانهم من هذا الخير؟\nقَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ ٢٨\n(أوسطهم): أفضلهم وأقربهم إلى الخير؛ وهو أحد الإِخوة الثلاثة. والوسط يطلق على الأخْيَر الأفضلِ؛ قال تعالى: ﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾ [البقرة: ١٤٣]، وقال: ﴿حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ﴾ [البقرة: ٢٣٨]. ابن عاشور: ٢٩/٨٦.\nلماذا خص أوسطهم بالذكر؟\nإِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّٰتِ ٱلنَّعِيمِ ٣٤\nتقريبهم دل على رضاه سبحانه، ورضا صاحب الدار مطلوب قبل نظر الدار. البقاعي: ٢٠/٣١٧.\nما دلالة قوله: ﴿عِندَ رَبِّهِمۡ﴾؟\nيَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ ٤٢\nعوقبوا بنقيض ما كانوا عليه؛ لمَّا دُعوا إلى السجود في الدنيا وامتنعوا منه مع صحتهم وسلامتهم، كذلك عوقبوا بعدم قدرتهم عليه في الآخرة إذا تجلى الرب -عز وجل-؛ فيسجد له المؤمنون، ولا يستطيع أحد من الكافرين ولا المنافقين أن يسجد، بل يعود ظهر أحدهم طبقًا واحدًا. ابن كثير: ٤/٤٠٧.\nلماذا منعوا من السجود في ذلك اليوم؟"],[566,"§القلم ، الحاقة\nwords\nتَرهَقُهُمتَغشَاهُم.\nمَكظُومٌمَملُوءٌ غَمًّا.\nلَنُبِذَ بِالعَرَاءِلَطُرِحَ مِن بَطنِ الحُوتِ بِالأَرضِ الفَضَاءِ المُهلِكَةِ.\nوَهُوَ مَذمُومٌآتٍ بِمَا يُلاَمُ عَلَيهِ.\nلَيُزلِقُونَكَلَيُسقِطُونَكَ عَن مَكَانِكَ؛ بِنَظَرِهِم إِلَيكَ؛ عَدَاوَةً وَبُغضًا.\nعَاتِيَةٍشَدِيدَةِ الهُبُوبِ.\nحُسُومًامُتَتَابِعَةً؛ لاَ تَفتُرُ، وَلاَ تَنقَطِعُ.\nأَعجَازُ نَخلٍأُصُولُ نَخلٍ.\ndeeds\nحافظ على الصلوات الخمس مع الجماعة.\nانصح مسلمًا مصرًا على المعصية ولا تيأس.\nادع الله بحسن الخاتمة.\nguid\nالتذكير باليوم الآخر.\nعدم الاستعجال في انتظار نتائج الدعوة إلى الله تعالى.\nمعرفة حال الأمم السابقة وما أنزل الله عليهم من العقوبات.\nrefl\nخَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ ٤٣\nونسبة الخشوع إلى الأبصار -وهو الخضوع والذلة- لظهور أثره فيها. الشوكاني: ٥/٢٧٥.\nلماذا نسب الخشوع إلى الأبصار في الآية الكريمة؟\nوَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ ٤٣\nقال إبراهيم التيمي: \"يعني إلى الصلاة المكتوبة بالأذان والإقامة\"، وقال سعيد بن جبير: \"كانوا يسمعون حي على الفلاح فلا يجيبون\". البغوي: ٤/٤٥٤.\nماذا يعني قوله: ﴿وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ﴾؟\nفَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ٤٤\nأي سنستنزلهم إلى العذاب درجة فدرجة؛ بالإمهال وإدامة الصحة وازدياد النعمة، ﴿مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ﴾ أنه استدراج؛ بل يزعمون أن ذلك إيثار لهم وتفضل على المؤمنين، مع أنه سبب لهلاكهم. الألوسي: ١٥/٤١.\nما علامة استدراج الله سبحانه للمكذبين؟\nسَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ٤٤\nقال سفيان الثوري: \"نسبغ عليهم النعم وننسيهم الشكر\". وقال الحسن: \"كم مستدرج بالإحسان إليه؟! وكم مفتون بالثناء عليه؟! وكم مغرور بالستر عليه؟!\". وقال أبو روق: \"أي كلما أحدثوا خطيئة جددنا لهم نعمة وأنسيناهم الاستغفار\"... وفي الحديث: «أن رجلًا من بني إسرائيل قال: يارب كم أعصيك وأنت لا تعاقبني! قال: فأوحى الله إلى نبي زمانهم أن قل له: كم من عقوبة لي عليك وأنت لا تشعر؛ إن جمود عينيك وقساوة قلبك استدراج مني وعقوبة لو عقلت». القرطبي: ٢١/١٨٠.\nما المراد بالاستدراج في الآية؟\nفَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ ٤٨\nهو يونس -عليه السلام- وسماه صاحب الحوت؛ لأن الحوت ابتلعه، وهو أيضًا ذو النون، والنون هو الحوت، وقد ذكرنا قصته في الأنبياء والصافات؛ فنهى الله محمدًا -صلى الله عليه وسلم- أن يكون مثله في الضجر والاستعجال حين ذهب مغاضبًا. ابن جزي: ٢/٤٩٤.\nما الأمر الذي نُهي النبي -صلى الله عليه وسلم- أن يكون مثله فيه؟\nوَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ ٥١\nأي: يَعينونك بأبصارهم، بمعنى: يحسدونك؛ لبغضهم إياك، لولا وقاية الله لك وحمايته إياك منهم. وفي هذه الآية دليل على أن العين إصابتها وتأثيرها حق بأمر الله -عز وجل-. ابن كثير: ٤/٤٠٨.\nيستدل بهذه الآية على أن العين حقيقة؛ وضّح ذلك.\nوَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٥٢\nأي والحال أن هذا القرآن أو الرسول -صلى الله عليه وسلم- (ما هو إلا ذكر) أي: موعظة وشرف (للعالمين) أي: كلهم؛ عاليهم ودانيهم؛ ليس منهم أحد إلا وهو يعلم أنه لا شيء يشبهه في جلالة معانيه، وحلاوة ألفاظه، وعظمة سبكه، ودقة فهمه، ورقة حواشيه، وجزالة نظومه، ويفهم منه على حسب ما هيأه الله له. البقاعي: ٢٠/٣٣٦.\nلماذا لا نَمَلُ من قراءة القرآن؟"],[567,"§الحاقة\nwords\nوَالمُؤتَفِكَاتُأَهلُ قُرَى قَومِ لُوطٍ الَّذِينَ انقَلَبَت بِهِم دِيَارُهُم.\nبِالخَاطِئَةِبِالفَعَلاَتِ ذَاتِ الخَطَإِ الجَسِيمِ.\nرَابِيَةًبَالِغَةً فِي الشِّدَّةِ.\nوَاهِيَةٌضَعِيفَةٌ، مُستَرخِيَةٌ.\nهَاؤُمُخُذُوا.\nفَغُلُّوهُاجمَعُوا يَدَيهِ إِلَى عُنُقِهِ بِالأَغلاَلِ.\nصَلُّوهُأَدخِلُوهُ، وَأَحرِقُوهُ بِهَا.\nذَرعُهَاطُولُهَا بِذِرَاعِ المَلَكِ.\ndeeds\nادع الله أن تأخذ كتابك باليمين يوم القيامة.\nتصدق بصدقة.\nأطعم مسكينًا.\nguid\nترك معاصي الخلوات فالله لا تخفى عليه خافية.\nالتذكير بشدة أهوال يوم القيامة.\nالمال والسلطان لا يغنيان عن العبد شيئًا إذا نزل به عذاب الله تعالى.\nrefl\nوَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ ١٢\nفالوعيُ توصف به الأذن كما يوصف به القلب؛ يقال: قلب واعٍ، وأذن واعية؛ لِمَا بين الأذن والقلب من الارتباط؛ فالعلم يدخل من الأذن إلى القلب، فهي بابه والرسول والموصل إليه العلم، كما أن اللسان رسوله المؤدي عنه. ومن عرف ارتباط الجوارح بالقلب علم أن الأذن أحقها أن توصف بالوعي، وأنها إذا وعت وعى القلب. ابن القيم: ٣/١٨٩.\nما سبب وصف الأذن بالواعية؟\nلِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةٗ وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ ١٢\nوالوعي: العلم بالمسموعات، أي: ولتعلم خبرها أذن موصوفة بالوعي، أي: من شأنها أن تعي. وهذا تعريض بالمشركين؛ إذ لم يتعظوا بخبر الطوفان والسفينة التي نجا بها المؤمنون، فتلقوه كما يتلقون القصص الفكاهي. ابن عاشور: ٢٩/١٢٣.\nفي الآية تعريض بالمشركين؛ وضحه.\nإِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ حِسَابِيَهۡ ٢٠\nكلما كان الإنسان أعلى كان الاستشعار والنقص من نفسه أكثر... يكفي العاقل في الخوف الحامل له على العمل. البقاعي: ٢٠/٣٦٢.\nما علامة كمال العقل عند الانسان؟\nكُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ ٢٤\nوثبت في الصحيح عن النبي -صلى الله عليه وسلم- أنه قال: «لن يدخل الجنة أحد بعمله»، قالوا: ولا أنت يا رسول الله؟ قال: «ولا أنا، إلا أن يتغمدني الله برحمة منه وفضل». ابن تيمية: ٦/٣٨٨.\nمتى ينفع العمل الصالح صاحبه؟\nثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ ٣٢ إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ ٣٣ وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ٣٤\nكان أبو الدرداء -رضي الله تعالى عنه- يحض امرأته على تكثير المرق لأجل المساكين، ويقول: «خلعنا نصف السلسلة بالإيمان أفلا نخلع نصفها»؛ اقتَبَس ذلك من الآية. الألوسي: ١٥/٥٧.\nما جزاء الإيمان والنفقة على المساكين إذا اجتمعا في المؤمن؟\nوَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ٣٤\nووصفه بأنه (لا يحض على طعام المسكين) يدل على أنه لا يطعمه من باب أولى، وهذه الآية تدل على عظم الصدقة وفضلها؛ لأنه قرن منع طعام المسكين بالكفر بالله. ابن جزي: ٢/٤٩٤.\nكيف دلت الآية على عظم الصدقة؟\nإِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ ٣٣ وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ٣٤\nلأن مدار السعادة ومادتها أمران: الإخلاص لله؛ الذي أصله الإيمان بالله، والإحسان إلى الخلق بوجوه الإحسان؛ الذي من أعظمها دفع ضرورة المحتاجين بإطعامهم ما يتقوتون به، وهؤلاء لا إخلاص ولا إحسان؛ فلذلك استحقوا ما استحقوا. السعدي: ٨٨٤.\nلماذا وُصِفَ أهل الشقاء بأنهم لا يؤمنون بالله العظيم ولا يحضون على طعام المسكين؟"],[568,"§الحاقة ، المعارج\nwords\nغِسلِينٍصَدِيدِ أَهلِ النَّارِ.\nتَقَوَّلَاختَلَقَ، وَافترَى عَلَينَا.\nالوَتِينَنِيَاطَ القَلبِ، وَهُوَ: عِرقٌ مُتَّصِلٌ بِهِ إِذَا قُطِعَ مَاتَ صَاحِبُهُ.\nذِي المَعَارِجِصَاحِبِ العُلُوِّ وَالجَلاَلِ.\nكَالمُهلِمِثلِ حُثَالَةِ الزَّيتِ.\nكَالعِهنِكَالصُّوفِ المَصبُوغِ المَنفُوشِ الَّذِي ذَرَتهُ الرِّيحُ.\ndeeds\nقل: \"اللهم إني أعوذ بك أن أقول زورًا أو أغشى فجورًا\".\nقل: \"سبحان الله وبحمده سبحان الله العظيم\" ١٠٠ مرة.\nقل: \"اللهم اهدني لأحسن الأخلاق؛ لا يهدي لأحسنها إلا أنت\".\nguid\nإذا كان النبي -صلى الله عليه وسلم- خوطب بالتهديد إذا تقول على الله؛ فكيف بمن يفتي عن الله بغير علم؟!\nسوء خاتمة مدّعي النبوة.\nاليقين باليوم الآخر وشدة قربه يدعو أهل الإيمان للعمل.\nrefl\nتَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٤٣\nما تضمنه قوله: ﴿تَنزِيلٌ مِّن رَّبِّ ٱلۡعَٰلَمِينَ﴾ أن ربوبيته الكاملة لخلقه تأبى أن يتركهم سدى؛ لا يأمرهم، ولا ينهاهم، ولا يرشدهم إلى ما ينفعهم، ويحذرهم ما يضرهم، بل يتركهم هملًا بمنزلة الأنعام السائمة؛ فمن زعم ذلك لم يقدر رب العالمين قدره، ونسبه إلى ما لا يليق به تعالى. ابن القيم: ٣/١٩١.\nما علامة ربوبيته الكاملة -سبحانه وتعالى-؟\nوَإِنَّهُۥ لَتَذۡكِرَةٞ لِّلۡمُتَّقِينَ ٤٨\nأي من العالمين؛ لأنهم المنتفعون به لإقبالهم عليه إقبال مستفيد. البقاعي: ٢٠/٣٨٣.\nلماذا خص التذكرة بالمتقين؟\nفَٱصۡبِرۡ صَبۡرٗا جَمِيلًا ٥\n(فاصبر) أي: على أذاهم. ولا ينفك ذلك عن تبليغهم؛ فإنك شارفت وقت الانتقام منهم، أيها الفاتح الخاتم الذي لم أبين لأحد ما بينت على لسانه. والصبر: حبس النفس على المكروه. البقاعي: ٢٠/٣٩٢.\nهل يقتضي الصبر على الناس ترك دعوتهم؟ وضح ذلك.\nفَٱصۡبِرۡ صَبۡرٗا جَمِيلًا ٥\nيعني: صبرًا لا جزع فيه. الطبري: ٢٣/٦٠٣.\nما معنى الصبر الجميل؟\nإِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدٗا ٦ وَنَرَىٰهُ قَرِيبٗا ٧\nوالله يراه قريبًا؛ لأنه رفيق حليم لا يعجل، ويعلم أنه لا بد أن يكون، وكل ما هو آت فهو قريب. السعدي: ٨٨٦.\nإنه مضى على نزول هذه الآية أكثر من ١٤٠٠سنة فكيف يوصف يوم القيامة بأنه قريب مع طول هذه المدة؟\nيَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ ٨ وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٩\nفإذا كان هذا القلق والانزعاج لهذه الأجرام الكبيرة الشديدة؛ فما ظنك بالعبد الضعيف الذي قد أثقل ظهره بالذنوب والأوزار؟! السعدي: ٨٨٦.\nما فائدة ذكر تغير السماء والجبال؟\nوَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٩\nالعِهن هو الصوف؛ شبّه الجبال به في انتفاشه وتخلخل أجزائه. ابن جزي: ٢/٤٩٥.\nبيّن وجه الشبه بين العهن والجبال يوم القيامة."],[569,"§المعارج\nwords\nوَفَصِيلَتِهِعَشِيرَتِهِ.\nلَظَىجَهَنَّمُ تَتَلَهَّبُ نَارُهَا، وَتَتَلَظَّى.\nنَزَّاعَةً لِلشَّوَىتَنزِعُ بِشِدَّةِ حَرِّهَا جِلدَةَ الرَّأسِ، وَسَائِرَ أَطرَافِ البَدَنِ.\nفَأَوعَىأَمسَكَ مَالَهُ فِي وِعَاءٍ، وَلَم يُؤَدِّ حَقَّ اللهِ فِيهِ.\nهَلُوعًايَجزَعُ عِندَ المُصِيبَةِ، وَيَمنَعُ إِذَا أَصَابَهُ الخَيرُ. وتَفسِيرُ الهَلُوعِ جَاءَ فِي الآيَتَينِ بَعدَهَا.\nجَزُوعًاكَثِيرَ الأَسَى وَالحُزنِ.\ndeeds\nحافظ على الصلوات جماعة في المسجد.\nتصدق بصدقة.\nتذكر أمانة أو عهدًا عليك لأحد وأوف به.\nguid\nالصلاة الخاشعة تقي من الجزع واليأس.\nالوفاء بالعهد وعدم خيانة الأمانة.\nحفظ النفس عن الشهوات المحرمة.\nrefl\nيُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۢ بِبَنِيهِ ١١ وَصَٰحِبَتِهِۦ وَأَخِيهِ ١٢ وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ ١٣ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ يُنجِيهِ ١٤\nوبدأ -جل ثناؤه- بذكر البنين، ثم الصاحبة، ثم الأخ؛ إعلامًا منه عباده أن الكافر من عظيم ما ينزل به يومئذ من البلاء يفتدي نفسه، لو وجد إلى ذلك سبيلًا بأحب الناس إليه كان في الدنيا، وأقربهم إليه نسبًا. الطبري: ٢٣/٦٠٦.\nلِمَ رتب الله أقارب الإنسان بهذا الترتيب في هذه الآية؟\n۞إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا ١٩ إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا ٢٠ وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا ٢١ إِلَّا ٱلۡمُصَلِّينَ ٢٢\nفالنفس لا تكون إلا مريدة عاملة؛ فإن لم توفق للإرادة الصالحة وإلا وقعت فى الإِرادة الفاسدة والعمل الضار. وقد قال تعالى: ﴿إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا * إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا * وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا﴾؛ فأَخبر تعالى أَن الإنسان خلق على هذه الصفة، وأن من كان على غيرها فلأَجل ما زكاه الله به من فضله وإِحسانه. ابن القيم: ٣/١٩٦.\nإذا علمت أن لكل إنسان إرادة؛ فما واجبك؟\n۞إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا ١٩ إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا ٢٠ وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا ٢١ إِلَّا ٱلۡمُصَلِّينَ ٢٢\nوذكره الله على وجه الذم لهذه الخلائق؛ ولذلك استثنى منه المصلين؛ لأن صلاتهم تحملهم على قلة الاكتراث بالدنيا، فلا يجزعون من شرها، ولا يبخلون بخيرها. ابن جزي: ٢/٤٩٥.\nلماذا استثنى الله المصلين من الاتصاف بصفة الهلع؟\nوَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ ٢٧\nخائفون على أنفسهم مع ما لهم من الأعمال الفاضلة؛ استقصارًا لها، واستعظامًا لجنابه -عز وجل-؛ كقوله تعالى: ﴿وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ﴾ [المؤمنون: ٦٠]. الألوسي: ١٥/٧١.\nكلما زادت خشية العبد من ربه زاد عمله الصالح؛ وضّح ذلك من الآية.\nوَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ ٣٣\nلا يُعبد إِلا إِيَّاه بجَميعِ أَنواعِ العبادةِ؛ فَهذا هو تحقيق شهادة أَن لا إِلَه إِلا الله، ولهَذا حرَّم الله علَى النَّارِ من شهِد أَن لا إِلَه إِلا الله حقيقَةَ الشهادة. ومحَالٌ أَن يدخل النار مَن تحَقَّق بحَقيقَة هذه الشهادة وقَام بها؛ كَما قَال تعالَى: ﴿وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ﴾ فَيكُون قَائمًا بشهادته في ظَاهرِه وباطنهِ، في قَلبِه وقَالَبِه؛ فَإِن من النَّاسِ مَن تكُون شهادته ميِّتةً، ومنهم مَن تكُون نائمةً؛ إِذا نبهت انتبهت. ابن القيم: ٣/١٩٧.\nكيف تتحقق شهادة أَن لا إِلَه إِلا الله؟\nٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ ٢٣ وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ٣٤\nوكرر ذكر الصلاة لاختلاف ما وصفهم به أولًا وما وصفهم به ثانيًا؛ فإن معنى الدوام هو أن لا يشتغل عنها بشيء من الشواغل -كما سلف-، ومعنى المحافظة أن يراعى الأمور التي لا تكون صلاة بدونها. الشوكاني: ٥/٢٩٣.\nلماذا كرر ذكر الصلاة في السورة؟\nكَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ ٣٩\nوفي المقصود بهذا الكلام ثلاثة أوجه؛ أحدها: تحقير الإنسان والردّ على المتكبرين. الثاني: الردّ على الكفار في طمعهم أن يدخلوا الجنة؛ كأنه يقول: إنا خلقناكم مما خلقنا منه الناس، فلا يدخل أحد الجنة إلا بالعمل الصالح؛ لأنكم سواء في الخلقة. الثالث: الاحتجاج على البعث بأن الله خلقهم من ماء مهين، فهو قادر على أن يعيدهم؛ كقوله: ﴿أَلَمۡ يَكُ نُطۡفَةً مِّن مَّنِيّٖ يُمۡنَىٰ﴾ [القيامة: ٣٧]. ابن جزي: ٢/٤٩٥.\nجمعت هذه الآية ثلاثة معانٍ؛ ما هي؟"],[570,"§المعارج ، نوح\nwords\nبِمَسبُوقِينَلاَ أَحَدَ يَفُوتُنَا وَيُعجِزُنَا إِذَا أَرَدنَاهُ.\nالأَجدَاثِالقُبُورِ.\nنُصُبٍأَحجَارٍ تُعبَدُ مِن دُونِ اللهِ.\nيُوفِضُونَيُهَروِلُونَ، وَيُسرِعُونَ.\nتَرهَقُهُمتَغشَاهُم.\nوَاستَغشَوا ثِيَابَهُمتَغَطَّوا بِهَا؛ مُبَالَغَةً فِي كَرَاهِيَتِي.\nوَأَصَرُّواأَقَامُوا عَلَى كُفرِهِم.\ndeeds\nقل: \"اللهم إني أعوذ برضاك من سخطك، وبعفوك من عقوبتك، وبك منك؛ لا أحصي ثناء عليك، أنت كما أثنيت على نفسك\".\nقل: \"اللهم إني أعوذ بك من تحول عافيتك، وفجاءة نقمتك، وجميع سخطك\".\nأَدِّ عملًا دعويًا من إرسال رسالة، أو تسجيل صوتي أو مرئي، أو تقديم نصيحة، أو أي وسيلة أخرى مناسبة.\nguid\nعظيم قدرة الله تعالى.\nالتذكير بحال الخروج من القبور في ذلة وسرعة.\nالصبر ركن أساس في دعوة كل داعية.\nrefl\nفَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ ٤٢\nالخوض في الباطل ضد التكلم بالحق، واللعب ضد السعي الذي يعود نفعه على ساعيه؛ فالأول ضد العلم النافع، والثاني ضد العمل الصالح؛ فلا تكلم بالحق، ولا عمل بالصواب؛ وهذا شأن كل من أعرض عما جاء به الرسول؛ لا بُدَّ له من هذين الأمرين. ابن القيم: ٣/٢٠١.\nما علامة من أعرض عما جاء به الرسول -صلى الله عليه وسلم-؟\nخَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ ٤٤\nوفي ختام السورة الكريمة لهذا الوصف والوعيد الشديد تأييد للقول بأن سؤالهم في أولها: ﴿بِعَذَابٍ وَاقِعٍ﴾ إنَّما هو استخفاف واستبعاد؛ فبيَّن لهم تعالى بعد عرض السورة نهاية ما يستقبلون به ليأخذوا حذرهم ويرجعوا إلى ربهم؛ فارتبط آخر السورة بأولها. الشنقيطي: ٨/٣٠٥.\nما وجه المناسبة بين أول السورة وآخرها؟\nإِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ ١\nوعُدل عن أن يقال له: \"أنذر الناس\" إلى قوله: ﴿أَنۡ أَنذِرۡ قَوۡمَكَ﴾ إلهابًا لنفس نوحٍ؛ ليكون شديد الحرص على ما فيه نجاتهم من العذاب؛ فإن فيهم أبناءه وقرابته وأحبته. ابن عاشور: ٢٩/١٨٧.\nلماذا عدل عن أن يقال: \"أنذر الناس\" إلى قوله: ﴿أَنذِرۡ قَوۡمَكَ﴾؟\nقَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ٢\nافتتاح دعوته قومَه بالنداء؛ لطلب إقبال أذهانهم. ونداؤهم بعنوان أنهم قومه؛ تمهيدًا لقبول نصحه، إذ لا يريد الرجل لقومه إلاّ ما يريد لنفسه. وتصدير دعوته بحرف التوكيد؛ لأن المخاطبين يترددون في الخبر. ابن عاشور: ٢٩/١٨٨.\nما فائدة افتتاح نوح -عليه السلام- دعوته لقومه بوصفهم ب(يا قوم)؟\nأَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ ٣\nفجعل العبادة والتقوى لله وحده، وجعل الطاعة للرسول؛ فإنه من يطع الرسول فقد أطاع الله. ابن تيمية: ٦/٣٩٨.\nلماذا أمرهم نوح -عليه السلام- بعبادة الله وتقواه، ثم أمرهم بطاعته هو -عليه السلام-؟\nوَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ\nأي دعوتهم ليؤمنوا فتغفر لهم؛ فذكر المغفرة التي هي سبب عن الإيمان ليظهر قبح إعراضهم عنه؛ فإنهم أعرضوا عن سعادتهم. ابن جزي: ٢/٤٩٤.\nلم ذكر الله المغفرة ولم يذكر سببها وهو الإيمان؟\nثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا ٨ ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا ٩\nذكر أولًا أنه دعاهم بالليل والنهار، ثم ذكر أنه دعاهم جهارًا، ثم ذكر أنه جمع بين الجهر والإسرار؛ وهذه غاية الجد في النصيحة وتبليغ الرسالة -صلى الله تعالى عليه وآله وسلم-. ابن جزي: ٢/٤٩٥.\nعلى ماذا يدل تنوع طرق الدعوة من نوح -عليه السلام- لقومه؟"]])